insert into generations (id, model_id, code, slug, start_year, end_year, one_liner, intro, verdict, strengths, watchouts, faq, status, data_status, reviewed_at, body_type, length_mm, boot_litres) values
  ('bmw:serie-1:f40', 'bmw:serie-1', 'F40', 'f40', 2019, 2024, 'El primer Serie 1 con tracción delantera: más espacio dentro, menos sabor ''BMW'' al volante.', 'La tercera generación del BMW Serie 1 (F40) abandonó la tracción trasera de sus antecesores y pasó a la plataforma delantera UKL compartida con MINI y el X1. A cambio ganó habitabilidad trasera y maletero. Tiene sentido para quien quiere un compacto premium bien acabado y con buena tecnología, y no le importa perder el tacto trasero. El comprador debe fijarse en el motor concreto (los 118i/118d son los más razonables) y en el estado de la caja automática de doble embrague en las versiones más potentes.', 'Compacto premium sólido y práctico si aceptas que ya no conduce como un Serie 1 clásico. El 118d es la versión más equilibrada de ocasión.', '{"Interior bien acabado y con buena multimedia","Más espacio atrás y mejor maletero que la generación anterior","Motores diésel muy sobrios en viaje"}'::text[], '{"Cadena de distribución y EGR en el B47 diésel","Tirones o retenciones de la caja DCT en frío en versiones potentes","Neumáticos runflat caros de reemplazar"}'::text[], '[{"q":"¿El Serie 1 F40 tiene tracción trasera?","a":"No. Es el primer Serie 1 con tracción delantera (o total xDrive en las versiones tope). Si buscas tracción trasera necesitas un F20/F21 anterior."},{"q":"¿Qué motor lleva el 118d F40?","a":"El diésel 2.0 de la familia B47 (código B47D20), con unos 150 CV y 350 Nm."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas', 4319, 380),
  ('bmw:serie-2-gran-coupe:f44', 'bmw:serie-2-gran-coupe', 'F44', 'f44', 2020, 2024, 'Un Serie 1 con carrocería de berlina-coupé y portón: imagen a cambio de espacio en las plazas traseras.', 'El Serie 2 Gran Coupé (F44) comparte plataforma y mecánicas con el Serie 1 F40, pero con una carrocería de cuatro puertas de línea coupé y portón trasero. Es una compra emocional: se elige por diseño. Mecánicamente valen los mismos consejos que para el Serie 1: elegir bien el motor y revisar la caja automática.', 'Misma base que el Serie 1 F40 con carrocería más atractiva y algo menos de espacio útil atrás. Elige el motor con cabeza.', '{"Estética diferenciada frente a compactos convencionales","Buen equipamiento tecnológico","Comportamiento seguro y previsible"}'::text[], '{"Altura libre trasera justa para adultos altos","Mismos puntos mecánicos que el Serie 1 F40","Precio de ocasión aún alto respecto a alternativas"}'::text[], '[{"q":"¿Es lo mismo que un Serie 1?","a":"Comparte plataforma y motores con el Serie 1 F40, pero con carrocería de berlina-coupé de cuatro puertas."},{"q":"¿Cabe bien una familia?","a":"Delante va sobrado; atrás el espacio para la cabeza es ajustado por la caída del techo."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina 4 puertas', 4526, 430),
  ('bmw:serie-3:g20', 'bmw:serie-3', 'G20', 'g20', 2019, 2024, 'La berlina de referencia por dinámica y consumo: el 320d G20 sigue siendo el patrón a batir.', 'La séptima generación del BMW Serie 3 (G20) mantiene la tracción trasera y afina el equilibrio entre confort y dinámica. Es una de las berlinas más buscadas de ocasión en España por su combinación de imagen, tacto de conducción y consumos bajos en autovía. El comprador debe centrarse en el 320d por versatilidad, revisar el historial de mantenimiento con sellos oficiales y comprobar el estado de la cadena de distribución del diésel y de la caja automática ZF de 8 marchas.', 'Sigue siendo la berlina de referencia para quien hace kilómetros. El 320d G20 con mantenimiento al día es una compra muy sólida.', '{"Tracción trasera y chasis muy equilibrado","Consumo de autovía muy bajo en el 320d","Caja automática ZF de 8 marchas excelente"}'::text[], '{"Cadena de distribución del B47 (revisar ruido en frío)","Fugas por la bomba de agua eléctrica en el B48 gasolina","Costes de mantenimiento y neumáticos superiores a la media"}'::text[], '[{"q":"¿Qué motor lleva el BMW 320d G20?","a":"El diésel 2.0 turbo de la familia B47 (B47D20), con unos 190 CV y 400 Nm, asociado casi siempre a la caja automática de 8 marchas."},{"q":"¿El 320d G20 tiene distribución por correa o cadena?","a":"Por cadena, situada en la parte trasera del motor. Conviene atender a cualquier ruido metálico en arranque en frío y usar el aceite y los intervalos que indica la marca."},{"q":"¿Es mejor el 318d o el 320d?","a":"El 320d ofrece bastante más empuje por muy poco más de consumo. El 318d tiene sentido si el precio de compra es sensiblemente menor."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina 4 puertas', 4709, 480),
  ('bmw:serie-3:f30', 'bmw:serie-3', 'F30', 'f30', 2012, 2019, 'El Serie 3 de ocasión más abundante: buenas dinámicas y motores conocidos, con puntos débiles bien identificados.', 'La sexta generación del Serie 3 (F30) es hoy una de las berlinas de segunda mano más ofertadas en España. Mecánicamente hay dos mundos: los primeros motores N47 diésel, con fama de cadena de distribución delicada, y los posteriores B47, más fiables. En gasolina, el N20 y luego el B48. Es una compra interesante por precio si se elige bien el motor y se revisa el historial.', 'Compra racional si aciertas con el motor: busca preferentemente B47 diésel o B48 gasolina y huye de un N47 sin historial de cadena.', '{"Oferta amplia y precios ya contenidos","Dinámica de conducción muy buena para su antigüedad","Motores B47/B48 con buena reputación"}'::text[], '{"Cadena de distribución en los diésel N47 (2012-2014)","Consumo de aceite y carbonilla en gasolina de inyección directa","Fugas de la caja de aguas que mojan la electrónica bajo el salpicadero"}'::text[], '[{"q":"¿Qué motores del Serie 3 F30 hay que evitar?","a":"El diésel N47 de los primeros años sin historial claro de la cadena de distribución. Los B47 posteriores son más tranquilos."},{"q":"¿El 320d F30 es fiable?","a":"Con el motor B47 (a partir de 2015 aproximadamente) y mantenimiento correcto, es una mecánica robusta y muy sobria."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina 4 puertas', 4633, 480),
  ('bmw:serie-5:g30', 'bmw:serie-5', 'G30', 'g30', 2017, 2023, 'Berlina grande de viaje: el 520d G30 combina consumo de compacto con espacio y confort de representación.', 'La séptima generación del Serie 5 (G30) es una berlina de gran turismo muy capaz para quien hace muchos kilómetros de autovía. El 520d ofrece consumos sorprendentemente bajos para el tamaño del coche; el 530d añade el refinamiento del seis en línea. Hay que vigilar el equipamiento (muchas unidades muy equipadas encarecen las reparaciones) y el estado de la suspensión neumática trasera si la monta.', 'Mucho coche por el dinero en el mercado de ocasión. El 520d es la opción sensata; el 530d, el capricho razonable.', '{"Confort y aislamiento de nivel superior","520d con consumos muy bajos para su tamaño","Tecnología de asistencia a la conducción avanzada"}'::text[], '{"Suspensión neumática trasera (coste elevado si falla)","EGR y cadena en el B47 diésel","Reparaciones de electrónica y equipamiento caras"}'::text[], '[{"q":"¿Cuánto consume un 520d G30?","a":"En viaje puede moverse en torno a 5-5,5 l/100 km reales según conducción; en uso mixto sube ligeramente."},{"q":"¿Merece la pena el 530d frente al 520d?","a":"El 530d es más suave y contundente, pero más caro de comprar y mantener. Para uso normal, el 520d cumple de sobra."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina 4 puertas', 4936, 530),
  ('audi:a3:8y', 'audi:a3', '8Y', '8y', 2020, null, 'El compacto premium ''de manual'': acabados, tecnología y el conocido 2.0 TDI para quien hace kilómetros.', 'La cuarta generación del Audi A3 (8Y) usa la plataforma MQB evo del Grupo VW, compartida con Golf 8, León 4 y Octavia 4. Es una compra racional: buena percepción de calidad, mecánicas conocidas y red de servicio amplia. El comprador debe decidir entre el 1.5 TSI (gasolina, uso urbano-mixto) y el 2.0 TDI (diésel, muchos kilómetros), y revisar el comportamiento de la caja S tronic en las versiones que la montan.', 'Opción segura de compacto premium. 30 TDI/35 TDI para carretera, 35 TFSI para ciudad. Revisa la S tronic y el software actualizado.', '{"Calidad percibida y tecnología a bordo","2.0 TDI muy sobrio en viaje","Piezas y servicio disponibles en toda España"}'::text[], '{"Tirones del 1.5 TSI a baja carga en primeras series (actualización de software)","Mantenimiento de EGR/AdBlue en el 2.0 TDI","Mecatrónica de la caja S tronic en unidades con mucho uso urbano"}'::text[], '[{"q":"¿Qué diferencia hay entre el A3 8Y y el Golf 8?","a":"Comparten plataforma, motores y cajas. Cambian el diseño, los acabados interiores y el ajuste de suspensión; a nivel mecánico los consejos de compra son casi idénticos."},{"q":"¿1.5 TSI o 2.0 TDI en el A3 8Y?","a":"El 1.5 TSI para uso mayoritariamente urbano y pocos kilómetros al año; el 2.0 TDI si haces más de 20.000 km anuales con mucha carretera."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto (Sportback y Sedán)', 4343, 380),
  ('audi:a3:8v', 'audi:a3', '8V', '8v', 2012, 2020, 'Uno de los compactos premium de ocasión más vendidos: mecánica MQB conocida y amplia oferta.', 'La tercera generación del A3 (8V) inauguró la plataforma MQB y es hoy una compra de ocasión muy habitual. Los motores 1.6 TDI y 2.0 TDI (familia EA288) y el 1.4/1.5 TSI en gasolina están muy rodados. Conviene comprobar consumo de aceite en algunos gasolina antiguos y el estado de la distribución.', 'Compra de ocasión madura y previsible. El 2.0 TDI EA288 con historial es de lo más recomendable del segmento por ese precio.', '{"Amplísima oferta y precios ajustados","Mecánicas diésel EA288 sobrias y conocidas","Buena habitabilidad para su tamaño"}'::text[], '{"Consumo de aceite en gasolina EA211 de primeras series","Volante bimasa y EGR en diésel con muchos kilómetros","Desgaste de la mecatrónica DSG en uso urbano intensivo"}'::text[], '[{"q":"¿El A3 8V 1.6 TDI es fiable?","a":"Con mantenimiento correcto es un diésel sobrio y duradero; sufre más si el uso es solo urbano y de trayectos cortos por el filtro de partículas."},{"q":"¿Lleva correa o cadena de distribución?","a":"Los diésel EA288 y los TSI EA211 usan correa con intervalo de sustitución; respétalo aunque el coche vaya bien."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto (Sportback, Sedán, Cabrio)', 4310, 380),
  ('audi:a4:b9', 'audi:a4', 'B9', 'b9', 2015, 2023, 'La berlina premium ''de kilómetros'': 2.0 TDI, buen aislamiento y consumo bajo en autovía.', 'La generación B9 del Audi A4 es una de las berlinas premium más compradas por profesionales que hacen muchos kilómetros. El 2.0 TDI (150 o 190 CV) es el motor lógico; el 35 TFSI gasolina para quien rueda menos. Revisar el sistema AdBlue, la EGR y —en versiones quattro— el estado del embrague Haldex y de la transmisión.', 'Berlina de viaje muy competente. El 2.0 TDI 190 CV con caja S tronic y mantenimiento oficial es la combinación más buscada.', '{"Aislamiento y confort de marcha de nivel alto","2.0 TDI con consumos de autovía muy bajos","Interior duradero y bien construido"}'::text[], '{"Averías del sistema AdBlue/SCR en algunas unidades","Consumo de aceite en el 2.0 TFSI de primeras series","Coste de mantenimiento de la tracción quattro"}'::text[], '[{"q":"¿A4 2.0 TDI de 150 o 190 CV?","a":"El de 190 CV va notablemente más holgado y suele venir con caja automática; el de 150 CV es suficiente para uso tranquilo y algo más barato de comprar."},{"q":"¿El A4 B9 gasta mucho aceite?","a":"Los diésel no deberían; en algunos 2.0 TFSI gasolina de los primeros años sí conviene vigilar el nivel entre revisiones."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina y Avant', 4762, 460),
  ('audi:a5:f5', 'audi:a5', 'F5', 'f5', 2016, 2024, 'El A4 B9 con carrocería más atractiva: mismo fondo mecánico, imagen de coupé y Sportback práctico.', 'El Audi A5 F5 comparte plataforma y mecánicas con el A4 B9. El Sportback de cinco puertas es el más práctico y buscado. Valen los mismos consejos que para el A4: elegir entre 2.0 TDI y gasolina según kilómetros, y revisar AdBlue, distribución y, en quattro, la transmisión.', 'Si te gusta la estética y no necesitas el maletero de un Avant, es un A4 B9 con más encanto. El 40 TDI Sportback es la versión estrella de ocasión.', '{"Diseño más deseable que la berlina equivalente","Sportback combina línea coupé y portón práctico","Mecánicas compartidas con el A4, bien conocidas"}'::text[], '{"Mismos puntos que el A4 B9 (AdBlue, EGR, distribución)","Cabrio: revisar capota y sellados","Precio de ocasión con prima respecto al A4"}'::text[], '[{"q":"¿El A5 Sportback es un coupé?","a":"Es una carrocería de cinco puertas con portón y línea de coupé; combina estética e maletero práctico."},{"q":"¿Comparte motor con el A4?","a":"Sí, la gama mecánica es esencialmente la misma que la del A4 B9."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Coupé, Sportback y Cabrio', 4733, 465),
  ('mercedes-benz:clase-a:w177', 'mercedes-benz:clase-a', 'W177', 'w177', 2018, 2025, 'Compacto premium con el salpicadero MBUX de dos pantallas: mucha imagen, mecánica a elegir con cuidado.', 'La cuarta generación de la Clase A (W177) marcó tendencia por su interior digital. Mecánicamente comparte diésel con Renault en las versiones de acceso (180 d) y estrena el OM654 propio en las superiores (200 d). En gasolina, el 1.3 co-desarrollado con Renault (160/180) y el 2.0 M264 (250). El comprador debe revisar la caja de doble embrague 7G-DCT y el mantenimiento del sistema AdBlue.', 'Atractivo por diseño y tecnología. El A 200 d con el OM654 propio es la versión diésel a buscar; evita cadenas de mantenimiento incompletas.', '{"Interior MBUX moderno y bien acabado","OM654 (200 d) muy silencioso y sobrio","Buena insonorización para un compacto"}'::text[], '{"Tirones de la caja 7G-DCT en frío y en maniobras","Motor 1.3 (base Renault) con historial de consumo de aceite en algunos lotes","Reparaciones de electrónica y pantallas caras"}'::text[], '[{"q":"¿Qué motor lleva el Mercedes A 180 d?","a":"Un diésel 1.5 de origen Renault (familia OM608), con unos 95-116 CV según año."},{"q":"¿La caja automática de la Clase A da problemas?","a":"La 7G-DCT de doble embrague puede mostrar tirones a baja velocidad; conviene probar en frío y revisar si tiene actualizaciones de software aplicadas."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sedán', 4419, 370),
  ('mercedes-benz:cla:c118', 'mercedes-benz:cla', 'C118', 'c118', 2019, 2025, 'La Clase A con silueta de coupé de cuatro puertas: se compra por diseño, mecánica idéntica.', 'El CLA C118 comparte plataforma y motores con la Clase A W177, con una carrocería más baja y estilizada. El Shooting Brake añade practicidad. Los consejos de compra son los mismos que para la Clase A: elegir bien el motor, revisar la 7G-DCT y el mantenimiento del AdBlue.', 'Un Clase A más deseable estéticamente y algo menos práctico. El CLA 200 d Shooting Brake es la versión más equilibrada de ocasión.', '{"Diseño exterior muy logrado","Shooting Brake combina estética y maletero","Mismo interior tecnológico que la Clase A"}'::text[], '{"Visibilidad trasera y acceso a plazas traseras justos","Mismos puntos mecánicos que la Clase A W177","Precio de ocasión elevado"}'::text[], '[{"q":"¿El CLA es más grande que la Clase A?","a":"Es más largo y más bajo; por dentro el espacio para la cabeza atrás es más ajustado."},{"q":"¿Shooting Brake o berlina?","a":"El Shooting Brake ofrece un maletero más útil y mejor acceso, con la misma estética de coupé en el lateral."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina coupé y Shooting Brake', 4688, 460),
  ('mercedes-benz:clase-c:w206', 'mercedes-benz:clase-c', 'W206', 'w206', 2021, null, 'Berlina premium con interior ''de Clase S en pequeño'': toda la gama microhibridada.', 'La quinta generación de la Clase C (W206) apuesta por un interior muy digital y una gama de motores 2.0 (gasolina M264 y diésel OM654) con hibridación ligera de 48 V, además de variantes híbridas enchufables. Es una compra premium para quien prioriza confort y tecnología. Hay que valorar la complejidad electrónica y el coste de reparación fuera de garantía.', 'Berlina de gama alta muy completa y confortable. El C 220 d es la opción de ocasión más razonable para hacer kilómetros.', '{"Confort de marcha y aislamiento sobresalientes","Diésel OM654 sobrio y refinado","Interior tecnológico muy cuidado"}'::text[], '{"Complejidad del sistema de 48 V y su electrónica","Coste de reparaciones fuera de garantía","Maletero reducido en las versiones híbridas enchufables"}'::text[], '[{"q":"¿Todas las Clase C W206 son híbridas?","a":"Todas llevan al menos hibridación ligera de 48 V; además hay versiones híbridas enchufables con autonomía eléctrica real de varias decenas de kilómetros."},{"q":"¿Qué autonomía eléctrica tiene la C 300 e?","a":"La híbrida enchufable homologa en torno a 100 km WLTP; en uso real suele quedarse algo por debajo."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina y Estate', 4751, 455),
  ('volkswagen:golf:mk8', 'volkswagen:golf', 'Mk8', 'mk8', 2020, null, 'El compacto de referencia: mecánica intachable, interior digital que dividió a los compradores.', 'La octava generación del Golf mantiene la plataforma MQB evo y la gama de motores 1.0/1.5 TSI, 2.0 TDI y variantes mild-hybrid eTSI. Es un coche mecánicamente muy competente; la polémica se centró en el interior táctil y el software de infoentretenimiento de las primeras series, mejorado con actualizaciones. El comprador debe verificar que el sistema multimedia esté actualizado y probar la respuesta de la caja DSG.', 'Sigue siendo el patrón del segmento a nivel mecánico. Busca una unidad con el software al día y elige eTSI o TDI según kilómetros.', '{"Motores TSI/TDI muy conocidos y con buena red de servicio","Comportamiento equilibrado y buen aislamiento","Consumos contenidos, sobre todo en eTSI y TDI"}'::text[], '{"Software de infoentretenimiento de las primeras series (2020-2021)","Tirones del 1.5 TSI a baja carga sin la actualización aplicada","Climatización y controles táctiles poco intuitivos"}'::text[], '[{"q":"¿El Golf 8 tiene problemas de software?","a":"Las primeras series (2020-2021) tuvieron fallos de infoentretenimiento y conectividad. Volkswagen publicó actualizaciones; conviene confirmar que estén instaladas."},{"q":"¿Qué es un Golf eTSI?","a":"Una versión gasolina TSI con hibridación ligera de 48 V y caja DSG, que permite navegar ''a vela'' con el motor parado y reduce algo el consumo."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Variant', 4284, 381),
  ('volkswagen:golf:mk7', 'volkswagen:golf', 'Mk7', 'mk7', 2012, 2020, 'Probablemente el compacto de ocasión más recomendable por precio: mecánica MQB muy rodada.', 'La séptima generación del Golf es una de las compras de ocasión más seguras del mercado español. Motores 1.2/1.4 TSI, 1.6/2.0 TDI (EA288) y la deportiva GTI. Hay que distinguir el pre-restyling del restyling de 2017 (mejor multimedia) y vigilar consumo de aceite en algunos TSI antiguos y la mecatrónica DSG.', 'Compra de ocasión de bajo riesgo si el historial está claro. El 1.6 TDI o el 1.5 TSI del restyling son las apuestas más tranquilas.', '{"Fiabilidad global y red de talleres enorme","Amplísima oferta en todos los presupuestos","Buen confort y aislamiento para su antigüedad"}'::text[], '{"Consumo de aceite en 1.4 TSI de primeras series","Mecatrónica DSG (DQ200) en uso urbano intensivo","Bomba de agua/termostato de plástico en TSI"}'::text[], '[{"q":"¿Qué Golf 7 comprar de segunda mano?","a":"Preferiblemente del restyling (2017 en adelante), con motor 1.6 TDI o 1.5 TSI y caja manual o DSG con historial de mantenimiento."},{"q":"¿El DSG del Golf 7 da problemas?","a":"La caja seca DQ200 puede necesitar reparación de mecatrónica en coches muy urbanos; la DSG húmeda de las versiones más potentes es más robusta."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Variant', 4258, 380),
  ('volkswagen:polo:aw', 'volkswagen:polo', 'AW (Mk6)', 'aw', 2017, null, 'Utilitario ''que parece un Golf pequeño'': espacio, seguridad y el 1.0 TSI como motor lógico.', 'La sexta generación del Polo (plataforma MQB A0) creció hasta ofrecer un maletero y una habitabilidad notables para el segmento B. El 1.0 TSI de 95/110 CV es el motor recomendable; el 1.0 MPI atmosférico se queda corto con carga. Revisar el software multimedia del restyling de 2021 y el estado de la caja DSG si la monta.', 'Uno de los mejores utilitarios para uso familiar ocasional. El 1.0 TSI 95/110 con caja manual es la compra más equilibrada.', '{"Espacio interior y maletero de referencia en el segmento","1.0 TSI elástico y sobrio","Buena dotación de seguridad en versiones recientes"}'::text[], '{"1.0 MPI atmosférico justo de fuerza con el coche cargado","Carbonilla en admisión del TSI con uso solo urbano","Multimedia de primeras series algo lenta"}'::text[], '[{"q":"¿El Polo AW es tan grande como un Golf antiguo?","a":"En habitabilidad y maletero se acerca mucho a un Golf de hace dos generaciones."},{"q":"¿1.0 MPI o 1.0 TSI?","a":"El TSI turbo es claramente preferible salvo que el uso sea exclusivamente urbano y sin carga; el MPI atmosférico rinde poco en cuesta o cargado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4053, 351),
  ('volkswagen:tiguan:ad1', 'volkswagen:tiguan', 'AD1 (Mk2)', 'ad1', 2016, 2024, 'El SUV familiar ''sin sorpresas'': maletero grande, mecánica MQB conocida y buena imagen de ocasión.', 'La segunda generación del Tiguan es uno de los SUV compactos más vendidos de la década en España. Motores 1.5 TSI, 2.0 TSI y 2.0 TDI, con tracción delantera o total 4Motion. El comprador debe elegir motor según kilómetros, revisar el embrague Haldex y la caja DSG, y confirmar el estado del software del restyling de 2020.', 'SUV familiar de bajo riesgo. El 2.0 TDI 150 4Motion para quien hace kilómetros; el 1.5 TSI para uso urbano-mixto.', '{"Maletero muy amplio y modularidad de asientos","Mecánicas TSI/TDI muy conocidas","Buena habitabilidad y confort"}'::text[], '{"Mantenimiento del Haldex (aceite) en versiones 4Motion","Mecatrónica DSG en uso urbano","Bomba de agua de los TSI"}'::text[], '[{"q":"¿El Tiguan 4Motion necesita mantenimiento especial?","a":"Sí, el embrague Haldex de la tracción total requiere cambio de aceite periódico que muchos propietarios omiten."},{"q":"¿Qué maletero tiene el Tiguan Mk2?","a":"En torno a 615 litros con los asientos traseros adelantados, uno de los mejores del segmento."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4509, 615),
  ('seat:ibiza:kj', 'seat:ibiza', 'KJ (6F)', 'kj', 2017, null, 'El ''Polo español'': misma base MQB A0, precio algo más ajustado y estética más joven.', 'La quinta generación del SEAT Ibiza comparte plataforma MQB A0 con el Polo AW. Motores 1.0 MPI, 1.0 TSI y 1.5 TSI. El 1.0 TSI de 95/110 CV es la opción lógica. Revisar multimedia del restyling de 2021 y el estado de embrague y caja.', 'Utilitario racional y bien resuelto. El 1.0 TSI 95 con caja manual es la compra más sensata de ocasión.', '{"Buen espacio y maletero para el segmento","1.0 TSI sobrio y suficiente","Precio de ocasión más contenido que el Polo"}'::text[], '{"1.0 MPI flojo con carga o en cuesta","Carbonilla en admisión del TSI en uso urbano","Plásticos interiores algo justos en versiones básicas"}'::text[], '[{"q":"¿La Ibiza KJ es igual que el Polo?","a":"Comparten plataforma, motores y muchas piezas. Cambian diseño, ajuste de chasis y equipamiento; los consejos mecánicos son equivalentes."},{"q":"¿Qué motor de la Ibiza es más recomendable?","a":"El 1.0 TSI de 95 o 110 CV, por equilibrio entre prestaciones, consumo y fiabilidad."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4059, 355),
  ('seat:leon:kl', 'seat:leon', 'KL (Mk4)', 'kl', 2020, null, 'El compacto ''valor seguro'' del Grupo VW en clave deportiva y a mejor precio que Golf o A3.', 'La cuarta generación del SEAT León (KL) comparte plataforma MQB evo con Golf 8, A3 8Y y Octavia 4. Gama 1.0/1.5 TSI, eTSI mild-hybrid, 2.0 TDI y la híbrida enchufable e-Hybrid. Mismo consejo que en sus hermanos: verificar software de infoentretenimiento y probar la DSG.', 'Toda la mecánica del Golf 8 con una imagen más dinámica y precio de ocasión inferior. El 2.0 TDI 150 o el 1.5 eTSI son las apuestas seguras.', '{"Mecánicas compartidas con Golf/A3, bien conocidas","Sportstourer con maletero muy útil","Precio de ocasión atractivo frente a sus hermanos premium"}'::text[], '{"Software multimedia de las primeras series","Tirones del 1.5 TSI sin actualización","e-Hybrid: revisar salud de la batería y cargador"}'::text[], '[{"q":"¿El León Mk4 comparte motor con el Golf 8?","a":"Sí, la gama mecánica y las cajas de cambio son esencialmente las mismas."},{"q":"¿Merece la pena el León e-Hybrid de ocasión?","a":"Si puedes cargarlo a diario y haces trayectos cortos, el consumo se desploma; si no vas a enchufarlo, no compensa el sobreprecio ni el peso extra."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sportstourer', 4368, 380),
  ('seat:ateca:5fp', 'seat:ateca', '5FP', '5fp', 2016, null, 'SUV compacto sobre base de León: dinámico de conducir y con mecánicas del Grupo VW.', 'El SEAT Ateca comparte plataforma MQB con León, Golf y Tiguan. Motores 1.0/1.5 TSI, 2.0 TSI y 2.0 TDI, con opción de tracción total 4Drive. Es de los SUV compactos más agradables de conducir. Revisar Haldex en 4Drive y la caja DSG.', 'SUV compacto equilibrado y bien resuelto. El 1.5 TSI para ciudad y el 2.0 TDI 4Drive para quien necesita tracción y kilómetros.', '{"Comportamiento dinámico por encima de la media del segmento","Buen maletero y habitabilidad","Mecánicas conocidas y red de servicio amplia"}'::text[], '{"Mantenimiento del Haldex en 4Drive","Mecatrónica DSG en uso urbano","Multimedia básica algo pobre en versiones de acceso"}'::text[], '[{"q":"¿El Ateca es un Tiguan más barato?","a":"Comparten plataforma y motores, pero el Ateca es algo más corto, más económico y con un ajuste de chasis más dinámico."},{"q":"¿Necesito la tracción total 4Drive?","a":"Solo si vives en zona de nieve habitual, arrastras remolque o haces pistas; para uso normal, la tracción delantera basta y consume menos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4386, 510),
  ('cupra:formentor:km7', 'cupra:formentor', 'KM7', 'km7', 2020, null, 'El primer modelo propio de CUPRA: SUV coupé con gama que va del 1.5 TSI al VZ de más de 300 CV.', 'El CUPRA Formentor usa plataforma MQB evo. La gama abarca desde el 1.5 TSI cumplidor hasta el 2.0 TSI VZ de altas prestaciones con tracción total, pasando por híbridos enchufables e-Hybrid. El comprador debe definir muy bien qué versión quiere: el coste de mantenimiento y neumáticos de un VZ no tiene nada que ver con el de un 1.5.', 'SUV coupé con personalidad. El 1.5 TSI 150 para uso normal; el VZ solo si asumes su consumo, sus gomas y su seguro.', '{"Diseño diferenciado y buena calidad percibida","Gama muy amplia de prestaciones","Chasis capaz y divertido en versiones altas"}'::text[], '{"Costes de neumáticos y frenos elevados en VZ","Software de infoentretenimiento de primeras series","e-Hybrid: maletero reducido y necesidad de cargar para amortizarlo"}'::text[], '[{"q":"¿Qué motor lleva el Formentor VZ?","a":"El 2.0 TSI de la familia EA888 con 310-333 CV según versión y año, con tracción total y caja DSG."},{"q":"¿El Formentor 1.5 TSI es suficiente?","a":"Para uso diario y viajes sí; mueve el coche con soltura aunque no ofrezca las prestaciones de las versiones VZ."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV coupé', 4450, 420),
  ('cupra:leon:kl', 'cupra:leon', 'KL', 'kl', 2020, null, 'El León deportivo hecho marca aparte: del 1.5 eTSI al 2.0 TSI de 300 CV y el e-Hybrid enchufable.', 'El CUPRA León comparte plataforma con el SEAT León KL pero con enfoque prestacional. Las versiones más buscadas son el 2.0 TSI de 245/300 CV y el e-Hybrid. Revisar embrague/caja DSG, salud de la batería en e-Hybrid y estado de frenos y neumáticos en las versiones potentes.', 'Compacto deportivo con buena relación prestaciones/precio en ocasión. El 2.0 TSI 245 es el punto dulce; el 300 exige más presupuesto de uso.', '{"Prestaciones altas por el dinero","Base MQB conocida y fiable","Sportstourer une deportividad y maletero"}'::text[], '{"Desgaste de neumáticos y frenos","Software multimedia de primeras series","e-Hybrid: revisar batería y cargador"}'::text[], '[{"q":"¿CUPRA León o Formentor?","a":"Comparten mecánica; el León es más ligero y ágil, el Formentor tiene imagen de SUV y postura de conducción más alta."},{"q":"¿El 2.0 TSI de 300 CV lleva tracción total?","a":"En carrocería Sportstourer sí; en 5 puertas la versión de 300 CV suele ser de tracción delantera con diferencial autoblocante."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sportstourer', 4368, 380),
  ('skoda:octavia:nx', 'skoda:octavia', 'NX (Mk4)', 'nx', 2019, null, 'El rey del maletero por el dinero: espacio de segmento superior con mecánica del Grupo VW.', 'La cuarta generación del Škoda Octavia sobre MQB evo es la referencia en relación espacio/precio. Motores 1.0/1.5 TSI, eTSI, 2.0 TDI y e-Tec/e-Hybrid. El 2.0 TDI 150 es el motor lógico para quien hace kilómetros; el Combi ofrece un maletero enorme. Revisar software multimedia y caja DSG.', 'La compra racional definitiva si necesitas espacio. Octavia Combi 2.0 TDI 150 con historial es de lo más recomendable del mercado.', '{"Maletero y habitabilidad de clase superior","2.0 TDI muy sobrio en viaje","Detalles prácticos ''Simply Clever''"}'::text[], '{"Software de infoentretenimiento de primeras series","Tirones del 1.5 TSI sin actualización","Mecatrónica DSG en uso urbano intensivo"}'::text[], '[{"q":"¿Qué maletero tiene el Octavia Combi Mk4?","a":"En torno a 640 litros en el Combi y 600 en el liftback, cifras de segmento superior."},{"q":"¿El Octavia es un Golf con más maletero?","a":"Comparte plataforma y motores con el Golf 8, con más longitud, más espacio y precio más ajustado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina liftback y Combi', 4689, 600),
  ('skoda:karoq:nu', 'skoda:karoq', 'NU', 'nu', 2017, null, 'SUV compacto práctico y sin dramas: el Ateca checo, con asientos traseros VarioFlex opcionales.', 'El Škoda Karoq comparte plataforma MQB con Ateca y Tiguan. Motores 1.0/1.5 TSI y 2.0 TDI, con opción 4x4. Los asientos traseros VarioFlex (extraíbles individualmente) son un plus de practicidad poco común. Revisar Haldex en 4x4 y caja DSG.', 'SUV familiar racional y bien acabado. El 1.5 TSI para ciudad y el 2.0 TDI 150 para carretera; busca los asientos VarioFlex si priorizas modularidad.', '{"Practicidad y modularidad (VarioFlex)","Buen maletero y habitabilidad","Mecánicas del Grupo VW bien conocidas"}'::text[], '{"Mantenimiento del Haldex en 4x4","Mecatrónica DSG en uso urbano","Multimedia básica pobre en acabados de acceso"}'::text[], '[{"q":"¿Qué son los asientos VarioFlex del Karoq?","a":"Tres asientos traseros independientes que se deslizan y se pueden extraer del coche por completo, dejando una zona de carga plana muy amplia."},{"q":"¿El Karoq es igual que el SEAT Ateca?","a":"Comparten plataforma y motores; cambian diseño, equipamiento y algunos detalles de practicidad."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4382, 521),
  ('toyota:corolla:e210', 'toyota:corolla', 'E210', 'e210', 2019, null, 'El compacto híbrido de referencia por fiabilidad y consumo urbano: casi cero sorpresas mecánicas.', 'La duodécima generación del Toyota Corolla (E210) se vende en España casi exclusivamente con mecánica híbrida (1.8 de 122 CV y 2.0 de 152/196 CV de sistema). Es una de las compras de ocasión más tranquilas que existen: sin embrague convencional, sin correa de distribución, sin turbo y con baterías que están demostrando gran durabilidad. El Touring Sports añade practicidad.', 'Si buscas tranquilidad y bajo consumo urbano, es difícil de superar. El 1.8 para ciudad; el 2.0 si quieres más brío en carretera.', '{"Fiabilidad mecánica sobresaliente","Consumo urbano muy bajo (frecuentemente 4-5 l/100 km)","Mantenimiento barato y espaciado"}'::text[], '{"El cambio e-CVT ''estira'' de revoluciones al acelerar con fuerza","Maletero justo en la carrocería 5 puertas","Insonorización mejorable frente a rivales premium"}'::text[], '[{"q":"¿Cuánto dura la batería del Corolla híbrido?","a":"La batería de tracción está diseñada para la vida del coche; hay muchas unidades con más de 200.000 km sin sustituirla. Toyota ofrece extensión de garantía si se hacen las revisiones oficiales."},{"q":"¿El Corolla híbrido se enchufa?","a":"No. Es un híbrido autorrecargable: recupera energía en frenadas y retenciones, no necesita cable."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas, Sedán y Touring Sports', 4370, 361),
  ('toyota:yaris:xp210', 'toyota:yaris', 'XP210', 'xp210', 2020, null, 'Utilitario híbrido con consumos de récord en ciudad y la fiabilidad marca de la casa.', 'La cuarta generación del Toyota Yaris estrena plataforma GA-B y mecánica híbrida 1.5 de 116 CV de sistema (además de un 1.5 gasolina de acceso). En ciudad es de los coches de combustión más eficientes que se pueden comprar. El maletero es pequeño y el espacio trasero justo; a cambio, muy poco que temer mecánicamente.', 'El utilitario ideal para uso urbano y periurbano. El híbrido 116 con etiqueta ECO es la versión a buscar.', '{"Consumo urbano excepcional","Fiabilidad y mantenimiento económico","Buena dotación de seguridad (Toyota Safety Sense)"}'::text[], '{"Maletero y plazas traseras reducidos","Ruido de motor al acelerar con fuerza (e-CVT)","Tacto de plásticos interiores algo justo"}'::text[], '[{"q":"¿El Yaris híbrido tiene etiqueta ECO?","a":"Sí, el Yaris híbrido autorrecargable tiene etiqueta ECO de la DGT."},{"q":"¿Yaris híbrido o Yaris 1.5 gasolina?","a":"El híbrido consume bastante menos en ciudad y tiene mejor etiqueta; el 1.5 gasolina puro solo compensa si el precio de compra es muy inferior y el uso es de carretera."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 3940, 286),
  ('toyota:c-hr:ngx10', 'toyota:c-hr', 'AX10 (2ª gen)', 'ax10', 2023, null, 'SUV coupé de diseño rompedor con mecánica híbrida Toyota y opción enchufable.', 'La segunda generación del Toyota C-HR mantiene la apuesta por el diseño llamativo y añade una versión híbrida enchufable a las híbridas 1.8 y 2.0 convencionales. Comparte la fiabilidad del resto de la gama híbrida de Toyota. La visibilidad trasera y el espacio para la cabeza atrás siguen siendo puntos flojos.', 'Si te entra por los ojos, la mecánica no te va a dar disgustos. El 2.0 híbrido es la versión más equilibrada; el PHEV solo si vas a enchufarlo.', '{"Diseño exterior muy diferenciado","Fiabilidad de la mecánica híbrida Toyota","Buen equipamiento de serie"}'::text[], '{"Visibilidad trasera reducida","Espacio para la cabeza en plazas traseras justo","PHEV: sobreprecio que solo se amortiza cargando a diario"}'::text[], '[{"q":"¿El C-HR se enchufa?","a":"La segunda generación ofrece una versión híbrida enchufable (PHEV) además de las híbridas autorrecargables."},{"q":"¿Cuánto consume el C-HR híbrido?","a":"En uso mixto ronda 5 l/100 km; en ciudad puede bajar de esa cifra con conducción suave."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV coupé', 4362, 388),
  ('nissan:qashqai:j12', 'nissan:qashqai', 'J12', 'j12', 2021, null, 'El SUV que inventó el segmento, ahora con micro-hibridación y el peculiar sistema e-Power.', 'La tercera generación del Nissan Qashqai (J12) ofrece el 1.3 TCe mild-hybrid (co-desarrollado con Mercedes) y el sistema e-Power, en el que un motor de gasolina actúa solo como generador y las ruedas las mueve un motor eléctrico. El comprador debe entender bien la diferencia: el e-Power conduce como un eléctrico pero reposta gasolina, con consumos buenos en ciudad y más altos en autopista.', 'SUV familiar bien resuelto. El 1.3 TCe 140 para uso convencional; el e-Power si haces mucha ciudad y te gusta el tacto eléctrico.', '{"Habitabilidad y maletero holgados","e-Power ofrece conducción suave tipo eléctrico","Buen equipamiento tecnológico"}'::text[], '{"Consumo del e-Power en autopista más alto de lo esperado","Historial de consumo de aceite del 1.3 TCe en primeras series","CVT en versiones TCe con caja automática: tacto ''elástico''"}'::text[], '[{"q":"¿Cómo funciona el Qashqai e-Power?","a":"Un motor de gasolina genera electricidad y un motor eléctrico mueve las ruedas. No se enchufa y no tiene modo puramente térmico a las ruedas."},{"q":"¿El 1.3 TCe del Qashqai da problemas?","a":"Las primeras series del 1.3 TCe (2019-2021, también en Renault) tuvieron casos de consumo de aceite; en el J12 conviene revisar niveles e historial."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4425, 504),
  ('nissan:juke:f16', 'nissan:juke', 'F16', 'f16', 2019, null, 'SUV pequeño de diseño atrevido sobre plataforma de Clio: motor 1.0 TCe y opción híbrida.', 'La segunda generación del Nissan Juke se apoya en la plataforma CMF-B de la Alianza (Clio, Captur). Motor 1.0 TCe de 114 CV y, desde 2022, una versión híbrida 1.6. Más práctico que el Juke original pero aún con maletero y plazas traseras algo justos. Revisar la caja DCT de doble embrague en las versiones automáticas.', 'SUV urbano con personalidad. El 1.0 TCe manual para uso sencillo; el híbrido si haces mucha ciudad.', '{"Diseño diferenciado","Plataforma moderna compartida con Clio/Captur","Versión híbrida eficiente en ciudad"}'::text[], '{"Caja DCT de doble embrague en versiones automáticas","Espacio trasero y maletero ajustados","1.0 TCe algo justo con el coche cargado"}'::text[], '[{"q":"¿El Juke comparte mecánica con el Clio?","a":"Sí, comparte plataforma CMF-B y el motor 1.0 TCe con Clio y Captur."},{"q":"¿Hay Juke híbrido?","a":"Desde 2022 se ofrece el Juke Hybrid con el sistema E-Tech 1.6 de la Alianza."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4210, 422),
  ('peugeot:208:p21', 'peugeot:208', 'P21 (2ª gen)', 'p21', 2019, null, 'Utilitario de diseño e interior i-Cockpit; motor PureTech 1.2 con un asterisco importante sobre la correa.', 'La segunda generación del Peugeot 208 ofrece gasolina PureTech 1.2, diésel BlueHDi 1.5 y la variante eléctrica e-208. El PureTech 1.2 turbo tiene buenas prestaciones y consumo, pero las series de 2019-2021 arrastran la mala fama de la correa de distribución ''húmeda'' (bañada en aceite), que puede degradarse antes de tiempo y obstruir el circuito de lubricación. Es imprescindible comprobar si se ha sustituido y con qué kit.', 'Bonito y bien equipado, pero con el PureTech 1.2 hay que verificar sí o sí el estado y el historial de la correa de distribución.', '{"Diseño exterior e interior atractivos","PureTech 1.2 elástico y sobrio si está sano","e-208 como opción eléctrica urbana"}'::text[], '{"Correa de distribución ''húmeda'' del PureTech (series 2019-2021)","Volante pequeño del i-Cockpit incómodo para algunas posturas","Multimedia lenta en versiones de acceso"}'::text[], '[{"q":"¿Qué problema tiene la correa del Peugeot 208 PureTech?","a":"En motores 1.2 PureTech de 2019-2021, la correa de distribución va bañada en aceite y puede deshacerse antes de lo previsto, soltando partículas que obstruyen el filtro de aceite y la bomba. Conviene revisarla y adelantarse a su sustitución con el kit actualizado."},{"q":"¿El BlueHDi 1.5 del 208 es más fiable?","a":"El diésel 1.5 no tiene ese problema de correa, pero exige cuidar el sistema AdBlue y no es ideal para uso solo urbano."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4055, 311),
  ('peugeot:308:p5', 'peugeot:308', 'P5 (3ª gen)', 'p5', 2021, null, 'Compacto de imagen renovada con PureTech, BlueHDi e híbrido enchufable; SW muy práctico.', 'La tercera generación del Peugeot 308 estrena la plataforma EMP2 evolucionada y una imagen más afilada. Gama PureTech 1.2, BlueHDi 1.5, híbrido enchufable y, más tarde, híbrido de 48 V. El PureTech de esta etapa cambió a cadena de distribución en algunas versiones, lo que reduce (que no elimina) la preocupación del motor anterior. El SW ofrece un maletero excelente.', 'Compacto atractivo y bien planteado. Verifica si el PureTech de la unidad concreta lleva cadena o correa y su historial.', '{"Diseño y calidad percibida al alza","SW con maletero muy amplio","Consumos contenidos en BlueHDi y en el mHEV"}'::text[], '{"Confirmar tipo de distribución del PureTech (cadena/correa) según año y versión","Ergonomía del i-Cockpit no gusta a todo el mundo","PHEV: maletero y precio penalizados si no se carga"}'::text[], '[{"q":"¿El PureTech del 308 nuevo sigue teniendo el problema de la correa?","a":"Stellantis fue introduciendo mejoras y cadena en parte de la gama. Hay que verificar la ficha del motor concreto y su plan de mantenimiento."},{"q":"¿Qué maletero tiene el 308 SW?","a":"En torno a 600 litros, de los mejores del segmento de familiares compactos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y SW', 4367, 412),
  ('peugeot:3008:p84', 'peugeot:3008', 'P84 (2ª gen)', 'p84', 2016, 2023, 'SUV compacto de interior vistoso y buen maletero; gama PureTech, BlueHDi e híbrido enchufable.', 'La segunda generación del Peugeot 3008 destacó por su interior i-Cockpit y su relación equipamiento/precio. Motores PureTech 1.2/1.6, BlueHDi 1.5/2.0 e híbrido enchufable Hybrid/Hybrid4. Aplican las mismas cautelas del PureTech con la correa en las primeras series y del sistema AdBlue en los diésel.', 'SUV familiar con mucho gancho visual. El BlueHDi 1.5/2.0 con historial es la opción más tranquila; con PureTech, revisar correa.', '{"Interior llamativo y bien equipado","Buen maletero y habitabilidad","BlueHDi 2.0 con buena reputación de fiabilidad"}'::text[], '{"Correa ''húmeda'' del PureTech en series iniciales","Sistema AdBlue/SCR en los diésel","Hybrid4: coste de mantenimiento y batería"}'::text[], '[{"q":"¿Qué motor del 3008 es más fiable?","a":"El diésel BlueHDi 2.0 tiene muy buena reputación; el 1.5 BlueHDi también, cuidando AdBlue. En gasolina, verificar el estado de la correa del PureTech."},{"q":"¿El 3008 Hybrid4 tiene tracción total?","a":"Sí, el Hybrid4 añade un motor eléctrico en el eje trasero que le da tracción total en determinadas condiciones."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4447, 520),
  ('renault:clio:bja', 'renault:clio', 'BJA (5ª gen)', 'bja', 2019, null, 'Utilitario superventas con buen interior, maletero de referencia y una eficiente versión híbrida E-Tech.', 'La quinta generación del Renault Clio sobre plataforma CMF-B ofrece gasolina TCe 1.0, GLP, y el híbrido E-Tech 1.6, uno de los sistemas más eficientes del segmento en ciudad. El maletero es de los mayores de su clase. Revisar el 1.3 TCe (en versiones que lo montan) por el historial de consumo de aceite en primeras series y el tacto de la caja EDC de doble embrague.', 'Uno de los mejores utilitarios del mercado. El E-Tech híbrido para ciudad, el TCe 90/100 para uso sencillo, el GLP para minimizar coste por kilómetro.', '{"Maletero y habitabilidad de referencia","Híbrido E-Tech muy eficiente en ciudad","Interior bien acabado para el segmento"}'::text[], '{"Consumo de aceite del 1.3 TCe en primeras series","Caja EDC de doble embrague: tirones a baja velocidad","Multimedia básica pobre en acabados de acceso"}'::text[], '[{"q":"¿El Clio E-Tech se enchufa?","a":"No. Es un híbrido autorrecargable con una pequeña batería que se carga en marcha; tiene etiqueta ECO."},{"q":"¿Qué motor lleva el Clio TCe 90?","a":"El tricilíndrico 1.0 TCe turbo (familia H4D), con unos 90-100 CV según año."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4050, 391),
  ('renault:megane:bfb', 'renault:megane', 'BFB (4ª gen)', 'bfb', 2016, 2022, 'Compacto cómodo y de buen maletero (sobre todo el familiar), con el conocido 1.5 dCi como motor lógico.', 'La cuarta generación del Renault Mégane ofrece gasolina TCe 1.2/1.3 y diésel 1.5/1.6 dCi, además de una versión híbrida enchufable E-Tech al final de su vida comercial. El 1.5 dCi (Blue dCi en las últimas series) es un diésel muy sobrio y probado. El Sport Tourer familiar tiene un maletero muy útil. Revisar caja EDC y, en dCi, turbo y volante bimasa con kilómetros.', 'Compacto confortable y sin grandes sorpresas. El Blue dCi 115 con historial es la compra racional; el Sport Tourer si necesitas maletero.', '{"Confort de suspensión por encima de la media","1.5 dCi muy sobrio y conocido","Sport Tourer con buen maletero"}'::text[], '{"Consumo de aceite del 1.3 TCe en primeras series","Caja EDC de doble embrague en uso urbano","Turbo y volante bimasa del dCi con muchos kilómetros"}'::text[], '[{"q":"¿El 1.5 dCi del Mégane es fiable?","a":"Es uno de los diésel más fabricados de Europa; con mantenimiento correcto es muy duradero. Sufre más en uso exclusivamente urbano por el filtro de partículas."},{"q":"¿Qué maletero tiene el Mégane Sport Tourer?","a":"En torno a 550-580 litros, de los mejores entre los familiares compactos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sport Tourer', 4359, 384),
  ('renault:captur:hjb', 'renault:captur', 'HJB (2ª gen)', 'hjb', 2019, null, 'SUV urbano práctico con banqueta trasera deslizante y una eficiente versión híbrida E-Tech.', 'La segunda generación del Renault Captur comparte plataforma CMF-B con el Clio. Ofrece TCe 1.0/1.3, GLP, híbrido E-Tech y también híbrido enchufable E-Tech Plug-in. La banqueta trasera corredera permite priorizar espacio para las piernas o para el maletero. Revisar el 1.3 TCe (consumo de aceite en primeras series) y la caja EDC.', 'SUV pequeño versátil y bien resuelto. El E-Tech híbrido para ciudad; el TCe 90/GLP para minimizar coste; el PHEV solo si lo enchufas.', '{"Modularidad de la banqueta trasera deslizante","Híbrido E-Tech eficiente en ciudad","Buena imagen y calidad percibida"}'::text[], '{"Consumo de aceite del 1.3 TCe en primeras series","Caja EDC de doble embrague en uso urbano","PHEV: maletero reducido y sobreprecio si no se carga"}'::text[], '[{"q":"¿El Captur comparte mecánica con el Clio?","a":"Sí, plataforma CMF-B y toda la gama de motores, incluidos el híbrido E-Tech y el TCe."},{"q":"¿Hay Captur híbrido enchufable?","a":"Sí, el E-Tech Plug-in con una autonomía eléctrica de unas pocas decenas de kilómetros."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4227, 422),
  ('dacia:sandero:b8', 'dacia:sandero', 'B8 (3ª gen)', 'b8', 2020, null, 'El coche nuevo más barato del mercado, ahora con plataforma moderna y mecánica probada del Grupo Renault.', 'La tercera generación del Dacia Sandero adopta la plataforma CMF-B del Clio, lo que mejora mucho seguridad y comportamiento. Motores TCe 1.0 gasolina y, sobre todo, la versión ECO-G bifuel gasolina/GLP, muy popular por su bajo coste por kilómetro. Mecánica sencilla y barata de mantener; equipamiento justo pero suficiente.', 'Imbatible en coste de uso, sobre todo en GLP. El TCe 100 ECO-G es la versión estrella para quien quiere gastar poco.', '{"Coste de compra y mantenimiento muy bajo","Versión GLP con gran ahorro de combustible","Plataforma moderna compartida con Clio"}'::text[], '{"Insonorización y materiales básicos","TCe 90/100 justo con el coche muy cargado","Equipamiento de asistencias limitado en acabados de acceso"}'::text[], '[{"q":"¿El Sandero GLP pierde maletero?","a":"El depósito de GLP se aloja en el hueco de la rueda de repuesto, por lo que el maletero apenas se ve afectado."},{"q":"¿Cuánto se ahorra con el Sandero GLP?","a":"El GLP cuesta aproximadamente la mitad por litro que la gasolina; aunque el consumo en litros sube algo, el gasto por kilómetro baja de forma notable."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4088, 328),
  ('dacia:duster:hm', 'dacia:duster', 'HM (3ª gen)', 'hm', 2024, null, 'SUV con capacidad real fuera del asfalto a precio de utilitario; ahora con opción híbrida.', 'La tercera generación del Dacia Duster estrena la plataforma CMF-B y añade una versión híbrida 1.6 a la gama TCe y ECO-G GLP. Mantiene una opción 4x4 con reductora poco habitual en el segmento por el precio. Es un coche honesto: pocas florituras, buen despeje y mecánica conocida.', 'El SUV más coche-por-el-dinero del mercado. TCe/ECO-G para uso normal; 4x4 si de verdad pisas tierra; híbrido para ciudad.', '{"Relación capacidad/precio imbatible","Opción 4x4 real poco común a este precio","Mecánicas probadas del Grupo Renault"}'::text[], '{"Materiales y insonorización básicos","Híbrido: menos capacidad todoterreno que el 4x4","Equipamiento de asistencias limitado en acabados bajos"}'::text[], '[{"q":"¿El Duster híbrido tiene tracción total?","a":"No. La versión híbrida es de tracción delantera; la tracción total 4x4 se ofrece con motores TCe/ECO-G."},{"q":"¿El Duster 4x4 lleva reductora?","a":"Monta un sistema de tracción total con modos de conducción; no es un todoterreno con reductora clásica, pero su capacidad en pista supera a la media de SUV del segmento."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4343, 472),
  ('ford:focus:mk4', 'ford:focus', 'Mk4', 'mk4', 2018, 2025, 'El compacto que mejor se conduce de su segmento; 1.0 EcoBoost y 1.5 EcoBlue como motores lógicos.', 'La cuarta generación del Ford Focus destaca por su comportamiento dinámico y su confort de marcha. Motores 1.0 EcoBoost gasolina (con mHEV de 48 V desde 2020) y 1.5 EcoBlue diésel. El EcoBoost 1.0 de esta etapa resolvió los problemas de refrigeración de generaciones anteriores; el EcoBlue 1.5 usa correa de distribución ''húmeda'' con intervalo estricto.', 'Si valoras cómo se conduce un coche, es la referencia del segmento. 1.0 EcoBoost mHEV para uso mixto; 1.5 EcoBlue para muchos kilómetros, cuidando la correa.', '{"Dinámica y tacto de conducción sobresalientes","1.0 EcoBoost mHEV suave y sobrio","Buen confort de suspensión"}'::text[], '{"Correa de distribución ''húmeda'' del 1.5 EcoBlue (intervalo estricto)","Caja automática de 8 marchas: revisar tacto y actualizaciones","Multimedia SYNC 3 algo desfasada en las primeras series"}'::text[], '[{"q":"¿El 1.0 EcoBoost del Focus Mk4 da problemas de refrigeración?","a":"Los fallos del tubo de degas que afectaron a generaciones anteriores están corregidos en el Focus Mk4, especialmente en las versiones mHEV de 48 V."},{"q":"¿Cada cuánto se cambia la correa del 1.5 EcoBlue?","a":"Es una correa bañada en aceite con un intervalo de sustitución que conviene respetar de forma estricta (consultar el plan de mantenimiento de la unidad concreta)."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sportbreak', 4378, 375),
  ('ford:fiesta:mk8', 'ford:fiesta', 'Mk8', 'mk8', 2017, 2023, 'El utilitario más divertido de conducir de su época; 1.0 EcoBoost con o sin microhibridación.', 'La octava (y última) generación del Ford Fiesta mantiene el chasis más aplaudido del segmento B. Motor 1.0 EcoBoost gasolina en varias potencias, con mHEV de 48 V desde 2020, y la deportiva ST. El interior envejeció regular en materiales y multimedia, pero mecánicamente es una compra sólida en las series recientes.', 'El utilitario para quien disfruta conduciendo. El 1.0 EcoBoost 100/125 mHEV es la compra más equilibrada de ocasión.', '{"Comportamiento y dirección de referencia en el segmento","1.0 EcoBoost elástico y sobrio","Buena disponibilidad de recambios"}'::text[], '{"Materiales interiores y multimedia justos","Refrigeración del EcoBoost en series 2017-2019 (revisar historial)","Plazas traseras y maletero pequeños"}'::text[], '[{"q":"¿El Fiesta Mk8 es fiable?","a":"En líneas generales sí, sobre todo a partir de 2020 con la microhibridación. Conviene revisar el historial de refrigeración en las primeras unidades."},{"q":"¿Fiesta o Polo?","a":"El Fiesta gana en tacto de conducción; el Polo ofrece más espacio, mejor interior y una imagen de ocasión algo más valorada."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 3 y 5 puertas', 4040, 292),
  ('ford:puma:mk1', 'ford:puma', 'Mk1', 'mk1', 2019, null, 'SUV pequeño sobre base de Fiesta: se conduce como un utilitario ágil y tiene un maletero con truco.', 'El Ford Puma toma el chasis del Fiesta Mk8 y añade carrocería de SUV y el ''MegaBox'', un compartimento adicional impermeable bajo el suelo del maletero. Motor 1.0 EcoBoost mHEV de 48 V y, más tarde, una versión híbrida completa. Hereda las virtudes dinámicas del Fiesta con más espacio y practicidad.', 'De los SUV pequeños más agradables de conducir. El 1.0 EcoBoost mHEV 125/155 es la compra lógica de ocasión.', '{"Comportamiento ágil heredado del Fiesta","Maletero grande y práctico (MegaBox)","1.0 EcoBoost mHEV sobrio"}'::text[], '{"Materiales interiores mejorables","Refrigeración del EcoBoost en primeras unidades (revisar historial)","Confort de suspensión algo firme"}'::text[], '[{"q":"¿Qué es el MegaBox del Ford Puma?","a":"Un compartimento adicional de unos 80 litros bajo el suelo del maletero, impermeable y con desagüe, útil para objetos sucios o mojados."},{"q":"¿El Puma comparte mecánica con el Fiesta?","a":"Sí, comparte plataforma y el motor 1.0 EcoBoost; el Puma añade carrocería de SUV y más practicidad."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4186, 456),
  ('hyundai:tucson:nx4', 'hyundai:tucson', 'NX4', 'nx4', 2020, null, 'SUV familiar de diseño rompedor, gama muy amplia (gasolina, diésel, 48 V, híbrido y enchufable) y garantía larga.', 'La cuarta generación del Hyundai Tucson (NX4) ofrece una de las gamas de motores más completas del segmento: 1.6 T-GDi gasolina, 1.6 CRDi diésel (con 48 V opcional), híbrido 1.6 y híbrido enchufable. Buen espacio, buen maletero y la garantía de 5 años de la marca como respaldo. Revisar la caja DCT de doble embrague en las versiones que la montan.', 'SUV familiar muy completo y con respaldo de garantía. El híbrido 1.6 para uso mixto-urbano; el 1.6 CRDi para muchos kilómetros.', '{"Gama de motores muy amplia","Espacio y maletero generosos","Garantía de fábrica de 5 años"}'::text[], '{"Caja DCT de doble embrague: tacto en maniobras y en frío","Híbrido enchufable: sobreprecio si no se carga","Consumo del 1.6 T-GDi gasolina en autopista"}'::text[], '[{"q":"¿Qué motor del Tucson es más recomendable?","a":"El híbrido 1.6 para quien hace ciudad y uso mixto; el 1.6 CRDi diésel para quien supera los 20.000 km anuales con mucha carretera."},{"q":"¿El Tucson mantiene la garantía si lo compro de segunda mano?","a":"La garantía de 5 años de Hyundai es de fábrica y se transfiere al nuevo propietario mientras esté vigente y se hayan respetado las revisiones."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4500, 620),
  ('hyundai:i30:pd', 'hyundai:i30', 'PD', 'pd', 2017, 2024, 'Compacto racional con garantía larga; 1.0/1.5 T-GDi gasolina y la deportiva i30 N como guinda.', 'La tercera generación del Hyundai i30 (PD) es un compacto sin grandes alardes pero muy bien resuelto, con garantía de fábrica de 5 años. Motores 1.0 T-GDi, 1.5 T-GDi (con 48 V) y, en su día, 1.6 CRDi diésel. La versión i30 N es una deportiva muy valorada. El Tourer familiar tiene buen maletero.', 'Compra racional de compacto con respaldo de garantía. El 1.0 T-GDi para ciudad, el 1.5 T-GDi mHEV para uso mixto; el i30 N si buscas diversión.', '{"Garantía de fábrica de 5 años","Comportamiento equilibrado y buen confort","Tourer con maletero amplio"}'::text[], '{"Carbonilla en admisión de los T-GDi con uso solo urbano","Multimedia básica en acabados de acceso","i30 N: consumo de neumáticos y frenos"}'::text[], '[{"q":"¿El i30 es fiable?","a":"Tiene buena reputación de fiabilidad y el respaldo de la garantía de 5 años de Hyundai; los motores T-GDi requieren cuidar el aceite y evitar el uso exclusivamente de trayectos cortos."},{"q":"¿Qué diferencia hay entre el i30 y el i30 Fastback?","a":"El Fastback es una carrocería de cinco puertas con línea de coupé y el techo más bajo; pierde algo de espacio para la cabeza atrás."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas, Fastback y Tourer', 4340, 395),
  ('kia:sportage:nq5', 'kia:sportage', 'NQ5', 'nq5', 2021, null, 'El hermano del Tucson con 7 años de garantía: misma mecánica, diseño distinto y respaldo aún mayor.', 'La quinta generación del Kia Sportage (NQ5) comparte plataforma y motores con el Hyundai Tucson NX4: 1.6 T-GDi, 1.6 CRDi con 48 V, híbrido 1.6 e híbrido enchufable. Su gran baza es la garantía de 7 años de Kia. Espacio y maletero generosos. Revisar la caja DCT de doble embrague.', 'Si te convence sobre el Tucson, la garantía de 7 años inclina la balanza. El híbrido 1.6 para uso mixto; el 1.6 CRDi para carretera.', '{"Garantía de fábrica de 7 años","Mecánicas compartidas con el Tucson, bien conocidas","Espacio y equipamiento generosos"}'::text[], '{"Caja DCT de doble embrague en maniobras y en frío","Híbrido enchufable: solo rentable cargándolo","Consumo del 1.6 T-GDi gasolina en viaje"}'::text[], '[{"q":"¿El Sportage y el Tucson son el mismo coche?","a":"Comparten plataforma, motores y cajas. Cambian el diseño exterior e interior, el ajuste de suspensión y, sobre todo, la garantía (7 años Kia frente a 5 años Hyundai)."},{"q":"¿La garantía de 7 años se transfiere al comprar de segunda mano?","a":"Sí, es una garantía de fábrica ligada al coche y se transfiere mientras esté vigente y con las revisiones al día."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4515, 591),
  ('kia:ceed:cd', 'kia:ceed', 'CD', 'cd', 2018, 2024, 'Compacto con 7 años de garantía; hermano del i30 con carrocería SW muy práctica.', 'La tercera generación del Kia Ceed (CD) comparte plataforma y motores con el Hyundai i30: 1.0/1.5 T-GDi gasolina, 1.6 CRDi diésel e híbrido enchufable en el Ceed SW. Su ventaja es la garantía de 7 años de Kia. El Ceed SW (familiar) y el ProCeed (shooting brake) amplían la oferta de carrocerías.', 'Compra racional de compacto con la garantía más larga del mercado. El 1.0 T-GDi para ciudad y el 1.5 T-GDi mHEV para uso mixto.', '{"Garantía de fábrica de 7 años","Gama de carrocerías variada (5p, SW, ProCeed)","Mecánicas compartidas con el i30, conocidas"}'::text[], '{"Carbonilla en admisión de los T-GDi con uso solo urbano","Multimedia básica en acabados de acceso","PHEV solo en Ceed SW y solo rentable cargándolo"}'::text[], '[{"q":"¿El Ceed es igual que el i30?","a":"Comparten plataforma, motores y cajas; cambian diseño, equipamiento y la garantía (7 años Kia frente a 5 de Hyundai)."},{"q":"¿Qué es el ProCeed?","a":"Una carrocería tipo shooting brake (familiar de línea deportiva y techo bajo) derivada del Ceed, solo disponible en acabados altos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas, SW y Fastback (ProCeed)', 4310, 395),
  ('volkswagen:golf:mk6', 'volkswagen:golf', 'Mk6 (5K)', 'mk6', 2008, 2012, 'El Golf de ocasión barato por excelencia: bien construido, pero con motores TSI y DSG de esa época a vigilar.', 'La sexta generación del Golf es un usado muy asequible y todavía sólido de carrocería. La clave está en el motor: el 1.4 TSI (EA111) arrastra fama de cadena de distribución y consumo de aceite, mientras que el 1.6 TDI y sobre todo el 1.9/2.0 TDI son más tranquilos. La caja DSG seca (DQ200) puede necesitar reparación de mecatrónica.', 'Compra de bajo coste si eliges un diésel o un 1.2 TSI con historial y evitas el 1.4 TSI Twincharger sin facturas de cadena.', '{"Precio de ocasión muy bajo","Carrocería y acabados que envejecen bien","Diésel 1.6/2.0 TDI sobrios y conocidos"}'::text[], '{"Cadena de distribución y consumo de aceite en el 1.4 TSI (EA111)","Mecatrónica de la DSG DQ200 en uso urbano","Bomba de agua y termostato de plástico en los TSI"}'::text[], '[{"q":"¿Qué motor del Golf 6 evitar?","a":"El 1.4 TSI Twincharger (150-160 CV) sin historial de la cadena de distribución. El 1.2 TSI posterior y los diésel dan menos sustos."},{"q":"¿El Golf 6 1.6 TDI es fiable?","a":"Con mantenimiento correcto es un diésel duradero; sufre en uso solo urbano por el filtro de partículas."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Variant', 4199, 350),
  ('volkswagen:polo:6r', 'volkswagen:polo', '6R / 6C', '6r', 2009, 2017, 'Utilitario robusto y con buen precio de ocasión; el 1.2 TSI de primeras series pide revisar la cadena.', 'La quinta generación del Polo es un usado muy habitual en España. Motores 1.2 (atmosférico y TSI), 1.4 y 1.2/1.6 TDI. El 1.2 TSI de 2010-2014 tuvo problemas de cadena de distribución; el restyling de 2014 (6C) mejoró multimedia y detalles.', 'Buen utilitario de ocasión con el 1.2 atmosférico o un TDI; con 1.2 TSI, pedir facturas de la cadena.', '{"Fiabilidad general y red de talleres amplia","Buen comportamiento y aislamiento para el segmento","Oferta abundante y barata"}'::text[], '{"Cadena de distribución del 1.2 TSI (2010-2014)","Multimedia básica en versiones anteriores al restyling","Óxido en bajos en unidades mal cuidadas"}'::text[], '[{"q":"¿El Polo 6R 1.2 TSI da problemas?","a":"Las series 2010-2014 tuvieron fallos de cadena de distribución. Conviene revisar si se ha sustituido o elegir el 1.2 atmosférico."},{"q":"¿Diferencia entre 6R y 6C?","a":"El 6C es el restyling de 2014: mejor multimedia, algún motor nuevo y retoques estéticos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 3970, 280),
  ('seat:ibiza:6j', 'seat:ibiza', '6J / 6P', '6j', 2008, 2017, 'El utilitario de ocasión más común en España: barato de comprar y mantener, con motores VAG conocidos.', 'La cuarta generación del SEAT Ibiza compartió plataforma PQ25 con el Polo 6R. Motores 1.2/1.4 gasolina, 1.2/1.4 TSI y 1.2/1.6 TDI. El restyling de 2015 (6P) estrenó la familia EA211. Aplican las mismas cautelas de cadena en el 1.2 TSI antiguo.', 'Compra de coste mínimo con el 1.2 atmosférico o el 1.6 TDI; con 1.2 TSI de primeras series, revisar la cadena.', '{"Coste de compra y mantenimiento muy bajo","Piezas y talleres en todas partes","Motores TDI sobrios"}'::text[], '{"Cadena de distribución del 1.2 TSI EA111","Plásticos y multimedia básicos en las series iniciales","Embragues y volante bimasa en diésel con muchos km"}'::text[], '[{"q":"¿La Ibiza 6J es fiable?","a":"Mecánicamente sí, sobre todo con motores atmosféricos o diésel. El punto flojo son los acabados y el 1.2 TSI antiguo."},{"q":"¿Qué es la Ibiza 6P?","a":"El restyling de 2015, con motores de la familia EA211 (1.0 y 1.4 TSI, 1.4 TDI) y mejor equipamiento."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 3 y 5 puertas', 4052, 292),
  ('seat:leon:5f', 'seat:leon', '5F (Mk3)', '5f', 2012, 2020, 'Compacto de ocasión muy recomendable: plataforma MQB, motores conocidos y precio por debajo de Golf VII y A3 8V.', 'La tercera generación del León comparte la plataforma MQB con el Golf VII. Gama 1.0/1.2/1.4 TSI, 1.6/2.0 TDI y las deportivas Cupra. El restyling de 2016 mejoró la multimedia. El ST (familiar) tiene un maletero muy útil.', 'De lo mejor en relación calidad/precio del usado compacto. El 1.6 TDI o el 1.4 TSI del restyling son apuestas seguras.', '{"Mecánicas MQB compartidas con Golf VII, bien conocidas","Precio de ocasión inferior a sus hermanos premium","ST con buen maletero"}'::text[], '{"Consumo de aceite en 1.4 TSI de primeras series","Mecatrónica DSG DQ200 en uso urbano","Multimedia lenta antes del restyling de 2016"}'::text[], '[{"q":"¿El León Mk3 es un Golf VII más barato?","a":"Comparten plataforma y motores; el León suele salir más económico a igualdad de año y motor."},{"q":"¿1.6 TDI o 1.4 TSI en el León 5F?","a":"El 1.6 TDI para muchos kilómetros de carretera; el 1.4 TSI para uso mixto y menos kilómetros al año."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 3/5 puertas y ST', 4263, 380),
  ('audi:a4:b8', 'audi:a4', 'B8', 'b8', 2007, 2015, 'Berlina premium de ocasión asentada; el 2.0 TDI common-rail es el motor a buscar, el 2.0 TFSI antiguo consume aceite.', 'La generación B8 del A4 es un usado premium abundante. El 2.0 TDI evolucionó de bomba-inyector a common-rail (más suave y fiable). En gasolina, el 1.8/2.0 TFSI de esos años tiene fama de consumo de aceite por los segmentos. La tracción quattro añade coste de mantenimiento.', 'Compra sólida con el 2.0 TDI common-rail (a partir de 2011 aprox.) y mantenimiento documentado.', '{"Aislamiento y sensación de solidez","2.0 TDI common-rail sobrio y suave","Interior duradero"}'::text[], '{"Consumo de aceite en 1.8/2.0 TFSI (segmentos)","Cadena de distribución del TFSI en la zona trasera del motor","Volante bimasa y EGR en diésel con kilómetros"}'::text[], '[{"q":"¿El A4 B8 2.0 TFSI gasta aceite?","a":"Muchas unidades 2008-2011 sí, por el diseño de los segmentos. Audi aplicó mejoras; conviene comprobar consumo antes de comprar."},{"q":"¿Qué 2.0 TDI del A4 B8 comprar?","a":"El common-rail (CJC/CGL) a partir de 2011 aproximadamente, más refinado que el bomba-inyector inicial."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina y Avant', 4703, 480),
  ('bmw:serie-1:f20', 'bmw:serie-1', 'F20 / F21', 'f20', 2011, 2019, 'El último Serie 1 con tracción trasera: tacto de conducción único en el segmento, con los puntos débiles del N47 diésel.', 'La segunda generación del Serie 1 (F20/F21) mantuvo la tracción trasera. Los diésel N47 de los primeros años tienen fama de cadena de distribución; los B47 posteriores, más tranquilos. En gasolina, del N13 al B38/B48. El restyling de 2015 mejoró faros y multimedia.', 'El compacto para quien disfruta conduciendo. Busca 118d/120d con motor B47 o un 120i, y revisa el historial de cadena si es N47.', '{"Tracción trasera y equilibrio de chasis","Motores B47/B48 fiables","Buen valor de reventa"}'::text[], '{"Cadena de distribución del diésel N47 (2011-2014)","Espacio trasero y maletero justos","Neumáticos runflat caros"}'::text[], '[{"q":"¿El Serie 1 F20 es de tracción trasera?","a":"Sí, es el último Serie 1 con propulsión trasera (salvo variantes xDrive). El F40 posterior pasó a tracción delantera."},{"q":"¿Qué motor diésel del F20 evitar?","a":"El N47 de los primeros años sin historial de la cadena de distribución. El B47 (desde 2015 aprox.) es más fiable."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 3 y 5 puertas', 4324, 360),
  ('mercedes-benz:clase-c:w205', 'mercedes-benz:clase-c', 'W205', 'w205', 2014, 2021, 'Berlina premium de ocasión muy deseada; el C 220 d (OM651 primero, OM654 después) es el motor de kilómetros.', 'La cuarta generación de la Clase C ofreció un salto de calidad percibida. Diésel OM651 2.1 hasta 2018 y OM654 2.0 (más refinado) después. El restyling de 2018 estrenó multimedia y motores. Vigilar la suspensión (algunas con neumática AIRMATIC) y el sistema de admisión de los diésel.', 'Mucho coche premium por el dinero. El C 220 d con OM654 (2018 en adelante) es la opción más equilibrada.', '{"Confort y aislamiento notables","Interior con buena calidad percibida","Amplia oferta de carrocerías y acabados"}'::text[], '{"Colector de admisión y EGR en los diésel OM651","Suspensión neumática AIRMATIC (coste si falla)","Reparaciones de electrónica caras fuera de garantía"}'::text[], '[{"q":"¿OM651 u OM654 en el C 220 d W205?","a":"El OM654 (desde 2018) es bastante más silencioso y moderno. El OM651 anterior es más ruidoso pero muy probado."},{"q":"¿La Clase C W205 tiene problemas de óxido?","a":"Algunas unidades de primeros años tuvieron corrosión prematura en zonas puntuales; conviene revisar bajos y bordes de puertas."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina y Estate', 4686, 480),
  ('nissan:qashqai:j11', 'nissan:qashqai', 'J11', 'j11', 2013, 2021, 'El SUV compacto más vendido de su época en España: práctico y cómodo, con el 1.5 dCi y el 1.2/1.3 DIG-T como motores.', 'La segunda generación del Qashqai fue un superventas. Motores 1.5 dCi y 1.6 dCi diésel, 1.2 y 1.3 DIG-T gasolina. La caja CVT (Xtronic) de algunas versiones tiene tacto elástico y conviene probarla bien. El 1.2 DIG-T de primeras series tuvo consumo de aceite.', 'SUV familiar de ocasión muy racional. El 1.5 dCi con caja manual es la compra más tranquila.', '{"Habitabilidad y confort de marcha","1.5 dCi muy sobrio","Oferta enorme y precios contenidos"}'::text[], '{"Consumo de aceite en el 1.2 DIG-T (2014-2016)","Caja CVT Xtronic: tacto y fiabilidad a largo plazo","Turbo y volante bimasa del dCi con kilómetros"}'::text[], '[{"q":"¿El Qashqai J11 con cambio automático es fiable?","a":"La caja CVT Xtronic funciona bien mantenida, pero es cara de reparar y su tacto no gusta a todos. Pruébala en frío y en caliente."},{"q":"¿Qué motor del Qashqai J11 comprar?","a":"El 1.5 dCi para carretera y el 1.2/1.3 DIG-T para uso urbano-mixto, revisando niveles de aceite en los 1.2 antiguos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4377, 430),
  ('renault:clio:iv', 'renault:clio', 'IV (BH)', 'iv', 2012, 2019, 'Utilitario de ocasión atractivo y barato; el 1.5 dCi es un diésel de referencia, el 0.9/1.2 TCe pide revisar aceite.', 'La cuarta generación del Clio popularizó el diseño de 5 puertas con manillas traseras ocultas. Motores 0.9 y 1.2 TCe gasolina, 1.5 dCi diésel y 1.2 16V atmosférico. El 1.2 TCe (H5Ft) tuvo consumo de aceite y averías de segmentos en varias unidades.', 'Compra de bajo coste con el 1.5 dCi o el 0.9 TCe con historial; vigilar niveles de aceite en los TCe.', '{"Diseño atractivo y buen maletero para el segmento","1.5 dCi muy sobrio y conocido","Precio de ocasión bajo"}'::text[], '{"Consumo de aceite y segmentos en el 1.2 TCe (2013-2018)","Caja automática EDC: tirones a baja velocidad","Electrónica y multimedia con fallos ocasionales"}'::text[], '[{"q":"¿El Clio IV 1.2 TCe da problemas?","a":"Varias unidades 2013-2018 consumen aceite por desgaste de segmentos. Revisar historial y nivel entre cambios."},{"q":"¿El 1.5 dCi del Clio IV es fiable?","a":"Es uno de los diésel más fabricados de Europa; muy duradero con mantenimiento, algo menos indicado para uso solo urbano."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4062, 300),
  ('peugeot:308:t9', 'peugeot:308', 'T9 (Mk2)', 't9', 2013, 2021, 'Compacto premiado en su lanzamiento; el 1.6 BlueHDi es un diésel muy sobrio, el 1.2 PureTech pide revisar la correa.', 'La segunda generación del 308 destacó por su ligereza y bajo consumo. Motores 1.2 PureTech gasolina y 1.5/1.6 BlueHDi diésel. El PureTech de esta etapa arrastra el asunto de la correa de distribución ''húmeda''. El SW familiar tiene un maletero excelente.', 'Compacto eficiente y agradable. El 1.6 BlueHDi con historial es la opción más tranquila; con PureTech, verificar la correa.', '{"Consumo real muy bajo","SW con maletero de referencia","Buen confort de suspensión"}'::text[], '{"Correa de distribución ''húmeda'' del 1.2 PureTech","Sistema AdBlue en los BlueHDi","Ergonomía del i-Cockpit no gusta a todos"}'::text[], '[{"q":"¿El 308 T9 PureTech tiene el problema de la correa?","a":"Sí, las unidades 2014-2021 con 1.2 PureTech deben revisar el estado y el historial de la correa de distribución bañada en aceite."},{"q":"¿Qué maletero tiene el 308 SW T9?","a":"En torno a 610 litros, uno de los mejores del segmento de familiares compactos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y SW', 4253, 420),
  ('ford:focus:mk3', 'ford:focus', 'Mk3', 'mk3', 2011, 2018, 'El compacto que mejor se conducía de su época; el 1.6 TDCi es sobrio, el 1.0 EcoBoost antiguo pide revisar la refrigeración.', 'La tercera generación del Focus mantuvo el listón dinámico alto. Motores 1.0 y 1.5/1.6 EcoBoost gasolina y 1.5/1.6 TDCi diésel. Los 1.0 EcoBoost de 2012-2017 tuvieron problemas de refrigeración (tubo de degas). El restyling de 2014 mejoró interior y multimedia.', 'Compra por dinámica de conducción; el 1.6 TDCi con historial es la opción más tranquila, revisando refrigeración si es 1.0 EcoBoost.', '{"Comportamiento y tacto de conducción de referencia","1.6 TDCi sobrio","Buen confort de suspensión"}'::text[], '{"Refrigeración del 1.0 EcoBoost (2012-2017)","Caja automática Powershift de doble embrague seco (tirones)","Multimedia SYNC anterior al restyling"}'::text[], '[{"q":"¿La caja automática del Focus Mk3 da problemas?","a":"La Powershift de doble embrague seco tuvo tirones y desgaste; muchas unidades recibieron campañas. Pruébala con calma o elige el manual."},{"q":"¿El 1.0 EcoBoost del Focus Mk3 es fiable?","a":"Las series 2012-2017 tuvieron fallos de refrigeración. Revisar historial de degas y bomba de agua."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sportbreak', 4358, 316),
  ('dacia:sandero:b52', 'dacia:sandero', 'B52 (2ª gen)', 'b52', 2012, 2020, 'El coche nuevo más barato de su década, ahora usado a precio de risa; mecánica Renault sencilla y conocida.', 'La segunda generación del Sandero usó plataforma del Clio III/IV. Motores 1.0/1.2 16V, 0.9 TCe, 1.5 dCi y la popular versión GLP. Equipamiento y materiales básicos, pero mecánica barata de mantener.', 'Coste de uso mínimo, sobre todo en GLP o 1.5 dCi. Perfecto para quien quiere gastar lo justo.', '{"Precio de compra y mantenimiento muy bajos","Versión GLP con gran ahorro","Mecánica Renault sencilla"}'::text[], '{"Materiales e insonorización pobres","0.9 TCe: revisar niveles de aceite","Equipamiento de seguridad limitado en acabados bajos"}'::text[], '[{"q":"¿El Sandero B52 GLP merece la pena?","a":"Sí si haces kilómetros: el GLP cuesta la mitad por litro y el depósito va en el hueco de la rueda de repuesto, sin perder maletero."},{"q":"¿Es fiable?","a":"Mecánicamente sí, con motores Renault muy probados. Lo justo son los acabados y el confort."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4069, 320),
  ('dacia:duster:hs', 'dacia:duster', 'HS (2ª gen)', 'hs', 2017, 2024, 'SUV con capacidad real fuera del asfalto a precio de utilitario; opción 4x4 poco común en el segmento.', 'La segunda generación del Duster mejoró mucho el interior y el aislamiento respecto a la primera. Motores TCe 1.0/1.3 gasolina, ECO-G GLP, Blue dCi 1.5 diésel y opción 4x4. Coche honesto y funcional.', 'El SUV más coche-por-el-dinero de ocasión. TCe/GLP para uso normal, 4x4 si de verdad pisas tierra.', '{"Relación capacidad/precio imbatible","Opción 4x4 real poco habitual a este precio","Mecánicas del Grupo Renault probadas"}'::text[], '{"Materiales e insonorización todavía básicos","1.3 TCe: revisar historial en primeras series","Equipamiento de asistencias limitado en acabados bajos"}'::text[], '[{"q":"¿El Duster HS 4x4 lleva reductora?","a":"No es un todoterreno con reductora clásica, pero su sistema de tracción total y su despeje superan a la media de SUV del segmento en pista."},{"q":"¿Diésel o gasolina en el Duster HS?","a":"El Blue dCi 1.5 para muchos kilómetros; el ECO-G GLP para minimizar el gasto por kilómetro en uso mixto."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4341, 445),
  ('volkswagen:passat:b8', 'volkswagen:passat', 'B8 (3G)', 'b8', 2014, 2023, 'Berlina familiar de kilómetros: 2.0 TDI sobrio, Variant con maletero enorme y confort de categoría superior.', 'La octava generación del Passat sobre plataforma MQB es una de las berlinas familiares más racionales de ocasión. Motores 1.4/1.5/2.0 TSI, 1.6/2.0 TDI y el híbrido enchufable GTE. El Variant tiene un maletero de referencia. Revisar la DSG y, en GTE, la batería.', 'Mucho coche por el dinero. Passat Variant 2.0 TDI 150 con historial es de lo más recomendable en familiares.', '{"Maletero y habitabilidad de clase superior","2.0 TDI muy sobrio en viaje","Confort y aislamiento notables"}'::text[], '{"Mecatrónica DSG en uso urbano","EGR y AdBlue en los 2.0 TDI","GTE: revisar salud de batería y cargador"}'::text[], '[{"q":"¿Qué maletero tiene el Passat Variant B8?","a":"En torno a 650 litros con los asientos en posición normal, de los mayores del segmento."},{"q":"¿El Passat GTE de ocasión compensa?","a":"Solo si puedes enchufarlo a diario; si no, cargas con el peso y el precio del sistema sin aprovecharlo."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina y Variant', 4767, 586),
  ('volkswagen:t-roc:a11', 'volkswagen:t-roc', 'A1 (A11)', 'a11', 2017, null, 'SUV compacto sobre base de Golf: dinámico de conducir, con mecánicas del Grupo VW muy conocidas.', 'El T-Roc comparte plataforma MQB con Golf y León. Gama 1.0/1.5 TSI, 2.0 TSI 4Motion y 2.0 TDI. El interior de primeras series usaba plásticos duros que el restyling de 2022 mejoró. Revisar DSG y, en 4Motion, el Haldex.', 'SUV urbano ágil y sin sorpresas. El 1.5 TSI para ciudad, el 2.0 TDI para carretera.', '{"Comportamiento dinámico por encima de la media","Mecánicas MQB conocidas","Buena imagen de ocasión"}'::text[], '{"Plásticos interiores duros antes del restyling de 2022","Mecatrónica DSG en uso urbano","Haldex en versiones 4Motion (cambio de aceite)"}'::text[], '[{"q":"¿El T-Roc es un Golf más alto?","a":"Comparte plataforma y motores con el Golf; cambian la carrocería SUV, la posición de conducción y el ajuste de suspensión."},{"q":"¿1.0 o 1.5 TSI en el T-Roc?","a":"El 1.0 TSI cumple en ciudad; el 1.5 TSI va más holgado en carretera y con el coche cargado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4234, 445),
  ('volkswagen:touran:5t', 'volkswagen:touran', '5T', '5t', 2015, null, 'Monovolumen familiar de verdad: 7 plazas usables, maletero enorme y mecánica del Grupo VW.', 'La tercera generación del Touran sobre MQB es de los pocos monovolúmenes compactos que quedan. Motores 1.2/1.5 TSI y 1.6/2.0 TDI. Las plazas de la tercera fila son aprovechables para niños y el maletero con 5 plazas es enorme.', 'La compra racional si necesitas 7 plazas de verdad. El 1.5 TSI para uso urbano-mixto, el 2.0 TDI para carretera.', '{"Habitabilidad y maletero de referencia","Modularidad de asientos muy práctica","Mecánicas conocidas"}'::text[], '{"Mecatrónica DSG en uso urbano","Tercera fila justa para adultos","EGR/AdBlue en los TDI"}'::text[], '[{"q":"¿El Touran 5T tiene 7 plazas de serie?","a":"Depende del acabado; muchas unidades llevan la tercera fila opcional. Verifica que la unidad concreta la tenga si la necesitas."},{"q":"¿Qué maletero tiene con 5 plazas?","a":"Más de 700 litros, de los mayores de cualquier compacto o familiar."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Monovolumen 5/7 plazas', 4527, 743),
  ('volkswagen:up:aa', 'volkswagen:up', 'AA / GG', 'aa', 2011, 2023, 'El urbano bien hecho: interior aprovechado, buen tacto y el 1.0 atmosférico o el e-up! eléctrico.', 'El VW up! (gemelo de SEAT Mii y Škoda Citigo) es un urbano de calidad superior a la media del segmento. Motores 1.0 atmosférico de 60/75 CV, 1.0 TSI de 90/115 CV y la versión eléctrica e-up!. Mecánica sencilla y barata.', 'El mejor urbano por refinamiento y percepción de calidad. El 1.0 atmosférico basta para ciudad; el e-up! si haces trayectos cortos.', '{"Interior bien aprovechado y bien acabado para el segmento","Mecánica 1.0 muy fiable y barata","Buen tacto de conducción"}'::text[], '{"1.0 atmosférico justo en autovía y cargado","Equipamiento básico en acabados de acceso","e-up!: autonomía real modesta en las primeras series"}'::text[], '[{"q":"¿El VW up! es lo mismo que el SEAT Mii?","a":"Sí, junto con el Škoda Citigo son el mismo coche con distinto emblema y pequeños detalles de equipamiento y precio."},{"q":"¿El e-up! sirve para ciudad?","a":"Sí, es su terreno; para viajes largos la autonomía y la carga son limitadas, sobre todo en las unidades anteriores a 2020."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Urbano 3 y 5 puertas', 3600, 251),
  ('audi:q3:f3', 'audi:q3', 'F3', 'f3', 2018, null, 'SUV premium compacto sobre MQB: buen espacio, interior de calidad y mecánicas compartidas con Tiguan y Ateca.', 'La segunda generación del Q3 creció en espacio y tecnología. Motores 1.5/2.0 TSI y 2.0 TDI, con tracción quattro opcional. Comparte plataforma con Tiguan, Ateca y Karoq, así que valen los mismos consejos: revisar DSG y Haldex.', 'SUV premium racional. El 35 TFSI para ciudad y el 35 TDI para quien hace kilómetros.', '{"Interior de calidad y buena tecnología","Espacio y maletero holgados","Mecánicas conocidas del Grupo VW"}'::text[], '{"Mecatrónica DSG en uso urbano","Haldex en versiones quattro (mantenimiento)","Precio de ocasión con prima frente a Tiguan/Ateca"}'::text[], '[{"q":"¿El Q3 F3 es un Tiguan premium?","a":"Comparte plataforma y motores; cambian el diseño, los acabados y el ajuste, con un precio de ocasión superior."},{"q":"¿Necesito quattro en el Q3?","a":"Solo si vives en zona de nieve, arrastras remolque o haces pista; para uso normal la tracción delantera consume menos y basta."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4485, 530),
  ('audi:q5:fy', 'audi:q5', 'FY', 'fy', 2017, null, 'SUV premium de kilómetros: 2.0 TDI quattro sobrio, buen confort y calidad de construcción.', 'La segunda generación del Q5 sobre plataforma MLB evo. Motores 2.0 TFSI y 2.0 TDI, tracción quattro de serie en la mayoría, y el híbrido enchufable 55 TFSI e. El restyling de 2020 renovó la multimedia. Vigilar el sistema de admisión de los diésel y la mecatrónica de la S tronic.', 'SUV premium equilibrado. El 40 TDI quattro con caja S tronic y mantenimiento oficial es la combinación más buscada.', '{"Confort y aislamiento de nivel alto","2.0 TDI quattro sobrio en viaje","Calidad de construcción"}'::text[], '{"EGR y admisión en los 2.0 TDI","Mecatrónica S tronic en uso urbano","Coste de mantenimiento de la tracción quattro"}'::text[], '[{"q":"¿El Q5 FY 2.0 TDI consume mucho?","a":"En viaje puede moverse en torno a 6 l/100 km reales para un SUV de su tamaño y peso."},{"q":"¿Merece la pena el Q5 55 TFSI e?","a":"Solo si cargas a diario y haces trayectos cortos; si no, el sobreprecio y el peso no compensan."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4663, 520),
  ('audi:a1:gb', 'audi:a1', 'GB (Mk2)', 'gb', 2018, null, 'Utilitario premium sobre MQB A0: mismo fondo que Polo e Ibiza, con acabado e imagen de Audi.', 'La segunda generación del A1 usa la plataforma MQB A0 de Polo e Ibiza. Motores 1.0/1.5/2.0 TSI gasolina (sin diésel). Interior digital y buena percepción de calidad; el precio de ocasión mantiene una prima notable sobre sus primos.', 'Utilitario premium si valoras la imagen y el interior. El 30 TFSI (1.0) para ciudad, el 35 TFSI (1.5) para carretera.', '{"Percepción de calidad e imagen de marca","Interior tecnológico","Mecánicas 1.0/1.5 TSI conocidas"}'::text[], '{"Sin versión diésel","Precio de ocasión alto frente a Polo/Ibiza","Carbonilla en admisión del TSI en uso solo urbano"}'::text[], '[{"q":"¿El A1 GB es un Polo con emblema de Audi?","a":"Comparte plataforma y motores con Polo e Ibiza; cambian diseño, acabados, tecnología y precio."},{"q":"¿Hay A1 diésel?","a":"No, la segunda generación solo se ofreció con motores de gasolina TSI."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4029, 335),
  ('bmw:x1:f48', 'bmw:x1', 'F48', 'f48', 2015, 2022, 'El primer X1 con tracción delantera: más espacio y practicidad, con los puntos del B47 diésel a vigilar.', 'La segunda generación del X1 pasó a la plataforma delantera UKL (compartida con MINI y Serie 2 Active Tourer). Ganó habitabilidad y maletero. Motores B38/B48 gasolina y B47 diésel, con tracción sDrive o xDrive. Revisar cadena y EGR del B47 y la caja de doble embrague en versiones potentes.', 'SUV compacto premium práctico. El sDrive18d con B47 y mantenimiento al día es la compra más racional.', '{"Espacio interior y maletero muy buenos para el tamaño","Diésel B47 sobrio en viaje","Buena posición de conducción"}'::text[], '{"Cadena de distribución y EGR del B47 diésel","Caja de doble embrague en versiones más potentes","Neumáticos runflat caros"}'::text[], '[{"q":"¿El X1 F48 es de tracción trasera?","a":"No, es el primer X1 con tracción delantera (o total xDrive en algunas versiones)."},{"q":"¿Qué motor lleva el X1 sDrive18d F48?","a":"El diésel 2.0 de la familia B47 (B47C20), con unos 150 CV."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4447, 505),
  ('bmw:x3:g01', 'bmw:x3', 'G01', 'g01', 2017, null, 'SUV medio premium de kilómetros: el xDrive20d combina consumo bajo, tracción total y buen aplomo.', 'La tercera generación del X3 sobre plataforma CLAR (trasera de base). Motores B47/B48 de 4 cilindros y B57 de 6 cilindros diésel, con tracción xDrive. El restyling de 2021 renovó la multimedia. Vigilar cadena y EGR de los diésel y, si la equipa, la suspensión adaptativa.', 'SUV medio muy capaz. El xDrive20d con B47 y mantenimiento documentado es la opción de kilómetros.', '{"Buen aplomo y tacto de conducción para un SUV","xDrive20d con consumos contenidos","Interior sólido y bien construido"}'::text[], '{"Cadena de distribución y EGR de los diésel B47","Coste de neumáticos y frenos","Reparaciones de electrónica caras fuera de garantía"}'::text[], '[{"q":"¿Cuánto consume un X3 xDrive20d G01?","a":"En viaje puede moverse en torno a 6-6,5 l/100 km reales para un SUV de tracción total de ese tamaño."},{"q":"¿20d o 30d en el X3 G01?","a":"El 30d (seis cilindros) es más suave y contundente, pero más caro de comprar y mantener. Para uso normal, el 20d cumple de sobra."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4708, 550),
  ('bmw:serie-4:g22', 'bmw:serie-4', 'G22 / G23 / G26', 'g22', 2020, null, 'El Serie 3 G20 con carrocería más atractiva: mismo fondo mecánico, imagen de coupé y Gran Coupé práctico.', 'La segunda generación del Serie 4 comparte plataforma y motores con el Serie 3 G20. El Gran Coupé de cinco puertas es el más práctico. Motores B48 gasolina y B47 diésel, con opción xDrive. Valen los mismos consejos que para el Serie 3.', 'Si te gusta la estética y no necesitas el maletero de una berlina, es un Serie 3 con más encanto. El 420d Gran Coupé es la versión más equilibrada de ocasión.', '{"Diseño más deseable que la berlina equivalente","Gran Coupé une línea coupé y portón práctico","Mecánicas compartidas con el Serie 3, conocidas"}'::text[], '{"Mismos puntos que el Serie 3 G20 (cadena B47, bomba de agua B48)","Cabrio: revisar capota y sellados","Precio de ocasión con prima sobre el Serie 3"}'::text[], '[{"q":"¿El Serie 4 comparte motor con el Serie 3?","a":"Sí, la gama mecánica y las cajas son esencialmente las mismas que las del Serie 3 G20."},{"q":"¿Coupé o Gran Coupé?","a":"El Gran Coupé tiene cuatro puertas, portón y más practicidad; el Coupé de dos puertas prioriza la estética."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Coupé, Cabrio y Gran Coupé', 4768, 440),
  ('mercedes-benz:clase-b:w247', 'mercedes-benz:clase-b', 'W247', 'w247', 2018, null, 'La Clase A en formato práctico: más altura, más maletero y mejor acceso, con el mismo interior MBUX.', 'La tercera generación de la Clase B comparte plataforma y motores con la Clase A W177. Diésel OM608 (180 d) y OM654 (200 d/220 d), gasolina 1.3 y 2.0. Interior digital MBUX. Revisar la caja 7G-DCT y el mantenimiento del AdBlue.', 'La opción sensata si quieres un compacto premium más práctico que la Clase A. El B 200 d con OM654 es la versión diésel a buscar.', '{"Habitabilidad y maletero superiores a la Clase A","Buen acceso y visibilidad","Interior MBUX moderno"}'::text[], '{"Tirones de la caja 7G-DCT en frío y maniobras","Mantenimiento del AdBlue en los diésel","Reparaciones de pantallas y electrónica caras"}'::text[], '[{"q":"¿La Clase B W247 es más práctica que la Clase A?","a":"Sí: más altura interior, mejor acceso a las plazas traseras y algo más de maletero, con la misma base mecánica."},{"q":"¿Qué motor lleva el B 180 d?","a":"Un diésel 1.5 de origen Renault (familia OM608), con unos 116 CV."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Monovolumen compacto', 4419, 455),
  ('mercedes-benz:gla:h247', 'mercedes-benz:gla', 'H247', 'h247', 2020, null, 'SUV compacto premium sobre la base de la Clase A: más alto y práctico, con el interior MBUX de dos pantallas.', 'La segunda generación del GLA comparte plataforma con la Clase A W177. Motores 1.3 y 2.0 gasolina, OM654 diésel y el híbrido enchufable 250 e. Revisar la caja de doble embrague y el AdBlue de los diésel.', 'SUV premium compacto con buena tecnología. El GLA 200 d es la opción diésel más equilibrada de ocasión.', '{"Interior MBUX moderno y bien acabado","Posición de conducción alta y buen acceso","OM654 diésel silencioso"}'::text[], '{"Caja 7G/8G-DCT: tacto en maniobras y en frío","Mantenimiento del AdBlue","Maletero reducido en la versión híbrida enchufable"}'::text[], '[{"q":"¿El GLA H247 es un Clase A más alto?","a":"Comparte plataforma, motores e interior con la Clase A; añade carrocería SUV, más altura libre y una postura de conducción elevada."},{"q":"¿Autonomía del GLA 250 e?","a":"Homologa en torno a 60-70 km eléctricos WLTP; en uso real algo menos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4410, 435),
  ('mercedes-benz:glc:x253', 'mercedes-benz:glc', 'X253', 'x253', 2015, 2022, 'SUV medio premium de kilómetros: el GLC 220 d 4MATIC combina confort, tracción total y consumo contenido.', 'La primera generación del GLC (sustituto del GLK) sobre plataforma de la Clase C W205. Diésel OM651 2.1 hasta 2019 y OM654 2.0 después; gasolina 2.0 y el híbrido enchufable 350 e. El restyling de 2019 renovó multimedia y motores. Vigilar admisión y EGR de los OM651.', 'SUV medio premium racional de ocasión. El GLC 220 d 4MATIC con OM654 (2019 en adelante) es la opción más equilibrada.', '{"Confort de marcha y aislamiento notables","Tracción total 4MATIC de serie en muchas versiones","Interior sólido"}'::text[], '{"Colector de admisión y EGR en los diésel OM651","Suspensión neumática AIRMATIC (coste si falla)","Reparaciones de electrónica caras"}'::text[], '[{"q":"¿OM651 u OM654 en el GLC 220 d?","a":"El OM654 (desde 2019) es más silencioso y moderno; el OM651 anterior es más ruidoso pero muy probado."},{"q":"¿El GLC Coupé pierde mucho maletero?","a":"Pierde algo de capacidad y sobre todo altura de carga frente al SUV normal, a cambio de la línea de techo descendente."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV y SUV Coupé', 4656, 550),
  ('seat:arona:kj7', 'seat:arona', 'KJ7', 'kj7', 2017, null, 'SUV pequeño sobre base de Ibiza: práctico, con buen maletero para el segmento y mecánicas 1.0/1.5 TSI.', 'El SEAT Arona comparte plataforma MQB A0 con la Ibiza. Motores 1.0 TSI, 1.5 TSI y, en su día, 1.6 TDI y GLP. Buen maletero y habitabilidad para un B-SUV. Revisar la DSG si la equipa.', 'B-SUV racional y bien resuelto. El 1.0 TSI 110 con caja manual es la compra más equilibrada.', '{"Buen maletero y habitabilidad para el segmento","1.0 TSI elástico y sobrio","Mecánicas conocidas del Grupo VW"}'::text[], '{"Carbonilla en admisión del TSI en uso solo urbano","Mecatrónica DSG en uso urbano","Plásticos interiores algo justos en acabados de acceso"}'::text[], '[{"q":"¿El Arona es un Ibiza más alto?","a":"Comparte plataforma y motores con la Ibiza; añade carrocería SUV, más altura libre y algo más de maletero."},{"q":"¿Hay Arona diésel?","a":"Las primeras series ofrecieron el 1.6 TDI; después la gama pasó a gasolina TSI y GLP."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4138, 400),
  ('seat:tarraco:kn2', 'seat:tarraco', 'KN2', 'kn2', 2018, null, 'El SUV grande de SEAT: 7 plazas, plataforma del Tiguan Allspace y mecánicas del Grupo VW.', 'El Tarraco comparte plataforma MQB con Tiguan Allspace y Škoda Kodiaq. Motores 1.5/2.0 TSI y 2.0 TDI, con opción 4Drive y el híbrido enchufable e-Hybrid. Tercera fila para uso ocasional. Revisar DSG y Haldex.', 'SUV familiar grande y racional. El 2.0 TDI 150 para quien hace kilómetros; el 1.5 TSI para uso urbano-mixto.', '{"Espacio y maletero muy amplios","Tercera fila usable ocasionalmente","Mecánicas conocidas del Grupo VW"}'::text[], '{"Mecatrónica DSG en uso urbano","Haldex en versiones 4Drive (mantenimiento)","e-Hybrid: maletero y precio penalizados si no se carga"}'::text[], '[{"q":"¿El Tarraco es un Kodiaq de SEAT?","a":"Comparten plataforma y motores; cambian diseño, ajuste de suspensión y equipamiento."},{"q":"¿La tercera fila del Tarraco vale para adultos?","a":"Para trayectos cortos o niños; para adultos en viaje largo se queda justa, como en casi todos los SUV de 7 plazas de este tamaño."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV 7 plazas', 4735, 700),
  ('skoda:fabia:nj', 'skoda:fabia', 'NJ (Mk3)', 'nj', 2014, 2021, 'Utilitario práctico y racional: maletero grande para el segmento, mecánicas VAG y precio de ocasión contenido.', 'La tercera generación de la Fabia sobre plataforma PQ26. Motores 1.0 MPI/TSI, 1.2 TSI y 1.4 TDI. Maletero y habitabilidad de referencia en el segmento B. El restyling de 2018 mejoró faros y multimedia.', 'Utilitario de bajo riesgo con el 1.0 TSI o el 1.0 MPI; el Combi si necesitas maletero.', '{"Maletero y habitabilidad de referencia","Detalles prácticos ''Simply Clever''","Mecánica VAG conocida"}'::text[], '{"1.0 MPI atmosférico justo con carga","Cadena del 1.2 TSI en las primeras unidades","Multimedia básica antes del restyling"}'::text[], '[{"q":"¿La Fabia NJ es fiable?","a":"Mecánicamente sí, sobre todo con los 1.0 atmosférico o TSI. El punto flojo son los acabados de las versiones básicas."},{"q":"¿Qué maletero tiene la Fabia Combi?","a":"En torno a 530 litros, uno de los mayores del segmento B."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas y Combi', 3997, 330),
  ('skoda:superb:3v', 'skoda:superb', '3V (B8)', '3v', 2015, null, 'El rey del espacio a precio de berlina media: habitabilidad de clase E y mecánica del Passat.', 'La tercera generación del Superb sobre plataforma MQB comparte motores con el Passat B8. Gama 1.4/1.5/2.0 TSI, 1.6/2.0 TDI y el híbrido enchufable iV. El Combi tiene un maletero enorme. Revisar DSG y, en 4x4, el Haldex.', 'La compra racional si necesitas mucho espacio por poco dinero. Superb Combi 2.0 TDI 150 con historial es de lo más recomendable.', '{"Habitabilidad trasera y maletero de clase superior","2.0 TDI muy sobrio en viaje","Confort y equipamiento por el dinero"}'::text[], '{"Mecatrónica DSG en uso urbano","EGR/AdBlue en los 2.0 TDI","Haldex en versiones 4x4 (mantenimiento)"}'::text[], '[{"q":"¿El Superb 3V es un Passat con más espacio?","a":"Comparte plataforma y motores con el Passat B8, con más longitud, más espacio trasero y precio más ajustado."},{"q":"¿Qué maletero tiene el Superb Combi?","a":"En torno a 660 litros, de los mayores de cualquier familiar del mercado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina liftback y Combi', 4869, 625),
  ('skoda:kamiq:nw4', 'skoda:kamiq', 'NW4', 'nw4', 2019, null, 'B-SUV práctico y bien resuelto: maletero amplio, buena habitabilidad y mecánicas 1.0/1.5 TSI.', 'El Škoda Kamiq comparte plataforma MQB A0 con Ibiza y Arona. Motores 1.0 TSI, 1.5 TSI y, en su día, 1.6 TDI y GLP. Uno de los B-SUV más espaciosos y racionales. Revisar la DSG si la equipa.', 'B-SUV racional con el 1.0 TSI 110; opción muy recomendable para uso familiar ocasional.', '{"Maletero y habitabilidad de referencia en el segmento","Detalles prácticos ''Simply Clever''","1.0 TSI elástico y sobrio"}'::text[], '{"Carbonilla en admisión del TSI en uso solo urbano","Mecatrónica DSG en uso urbano","Plásticos duros en acabados de acceso"}'::text[], '[{"q":"¿El Kamiq es un Arona checo?","a":"Comparten plataforma y motores; el Kamiq suele ofrecer algo más de espacio y practicidad."},{"q":"¿1.0 o 1.5 TSI en el Kamiq?","a":"El 1.0 TSI 110 cumple de sobra; el 1.5 TSI va más holgado en carretera y cargado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4241, 400),
  ('skoda:scala:nw1', 'skoda:scala', 'NW1', 'nw1', 2019, null, 'Compacto con maletero de familiar: el sustituto del Rapid, práctico y con mecánicas MQB A0.', 'El Škoda Scala sobre plataforma MQB A0 ocupa el hueco entre Fabia y Octavia. Motores 1.0 TSI, 1.5 TSI y 1.6 TDI. Su gran baza es un maletero enorme para un compacto y una habitabilidad muy buena.', 'Compacto racional si priorizas espacio y precio. El 1.0 TSI 110 es la compra más equilibrada.', '{"Maletero enorme para un compacto","Buena habitabilidad","Mecánicas conocidas y precio contenido"}'::text[], '{"Plásticos duros en acabados de acceso","Mecatrónica DSG en uso urbano","Insonorización mejorable frente a rivales premium"}'::text[], '[{"q":"¿El Scala es un Octavia pequeño?","a":"Es más corto y sencillo que el Octavia, pero comparte filosofía práctica y ofrece un maletero muy grande para su tamaño."},{"q":"¿Hay Scala diésel?","a":"Sí, con el 1.6 TDI en las primeras series; después la gama se centró en gasolina TSI."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas', 4362, 467),
  ('toyota:rav4:xa50', 'toyota:rav4', 'XA50', 'xa50', 2018, null, 'SUV familiar híbrido de referencia por fiabilidad: el 2.5 Hybrid con consumo contenido y opción de tracción total.', 'La quinta generación del RAV4 se vende en España sobre todo con el híbrido 2.5 (218-222 CV de sistema) y también como híbrido enchufable Plug-in. Mecánica sin turbo ni embrague convencional, con la fiabilidad marca de la casa. La tracción total E-Four añade un motor eléctrico en el eje trasero.', 'SUV familiar de tranquilidad total. El 2.5 Hybrid es la compra racional; el Plug-in solo si cargas a diario.', '{"Fiabilidad mecánica sobresaliente","Consumo contenido para un SUV grande","Mantenimiento barato y espaciado"}'::text[], '{"El cambio e-CVT ''estira'' de vueltas al acelerar con fuerza","Insonorización mejorable frente a rivales premium","Plug-in: sobreprecio que solo se amortiza cargando"}'::text[], '[{"q":"¿El RAV4 Hybrid tiene tracción total?","a":"Opcionalmente, con el sistema E-Four que añade un motor eléctrico en el eje trasero; no hay árbol de transmisión mecánico."},{"q":"¿Cuánto consume el RAV4 2.5 Hybrid?","a":"En uso mixto suele moverse en torno a 6 l/100 km reales, cifra baja para su tamaño y peso."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4600, 580),
  ('toyota:aygo:ab40', 'toyota:aygo', 'AB40', 'ab40', 2014, 2022, 'Urbano mínimo y fiable: el 1.0 VVT-i atmosférico, mantenimiento barato y cero sorpresas mecánicas.', 'La segunda generación del Aygo (gemelo de Peugeot 108 y Citroën C1) monta el tricilíndrico 1.0 VVT-i atmosférico. Coche pensado para ciudad: maletero mínimo y poco aislamiento, pero mecánica muy fiable y económica.', 'Urbano puro para quien quiere gastar lo mínimo. Fiable y barato; olvídate de autovías largas.', '{"Fiabilidad y mantenimiento muy baratos","Fácil de aparcar y manejar en ciudad","Consumo urbano contenido"}'::text[], '{"Maletero y plazas traseras mínimos","Poca insonorización y ruido en autovía","Equipamiento básico en acabados de acceso"}'::text[], '[{"q":"¿El Aygo AB40 es el mismo coche que el Peugeot 108?","a":"Sí, junto con el Citroën C1 comparten plataforma, motor y carrocería con pequeños cambios estéticos."},{"q":"¿Sirve para carretera?","a":"Para tramos cortos sí; en autovía larga es ruidoso y va justo de fuerza, sobre todo cargado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Urbano 3 y 5 puertas', 3465, 168),
  ('nissan:x-trail:t32', 'nissan:x-trail', 'T32', 't32', 2014, 2022, 'SUV familiar con opción de 7 plazas: hermano mayor del Qashqai, con el 1.6 dCi y el 1.3 DIG-T como motores.', 'La tercera generación del X-Trail comparte plataforma con el Qashqai J11. Motores 1.6 dCi diésel y 1.3/1.6 DIG-T gasolina, con opción de tercera fila. La caja CVT Xtronic de algunas versiones conviene probarla bien.', 'SUV familiar racional. El 1.6 dCi con caja manual es la compra más tranquila; la tercera fila solo para uso ocasional.', '{"Espacio y maletero holgados","Opción de 7 plazas poco común en el segmento","1.6 dCi sobrio"}'::text[], '{"Caja CVT Xtronic: tacto y fiabilidad a largo plazo","Turbo y volante bimasa del dCi con kilómetros","Tercera fila muy justa para adultos"}'::text[], '[{"q":"¿El X-Trail T32 es un Qashqai grande?","a":"Comparte plataforma y motores con el Qashqai J11; es más largo, con más maletero y opción de tercera fila."},{"q":"¿La caja automática del X-Trail es fiable?","a":"La CVT Xtronic funciona bien mantenida, pero es cara de reparar y su tacto es elástico. Pruébala en frío y en caliente."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV 5 y 7 plazas', 4690, 565),
  ('nissan:micra:k14', 'nissan:micra', 'K14', 'k14', 2017, 2023, 'Utilitario con diseño moderno sobre plataforma de Clio: motores 1.0 y 0.9 IG-T de la Alianza.', 'La quinta generación del Micra se apoya en la plataforma CMF-B de la Alianza (Clio, Captur). Motores 1.0 atmosférico, 0.9/1.0 IG-T turbo y 1.5 dCi diésel. Más largo y con mejor comportamiento que el Micra anterior, aunque con maletero y plazas traseras algo justos.', 'Utilitario correcto con el 1.0 IG-T turbo; el 1.0 atmosférico se queda corto con carga.', '{"Diseño moderno y buen comportamiento","Plataforma compartida con Clio/Captur","0.9/1.0 IG-T elásticos"}'::text[], '{"1.0 atmosférico justo de fuerza","Espacio trasero y maletero ajustados","Multimedia básica en acabados de acceso"}'::text[], '[{"q":"¿El Micra K14 comparte mecánica con el Clio?","a":"Sí, comparte la plataforma CMF-B y buena parte de los motores con Clio y Captur."},{"q":"¿Hay Micra diésel?","a":"Las primeras series ofrecieron el 1.5 dCi; después la gama pasó solo a gasolina."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 3999, 300),
  ('peugeot:2008:p24', 'peugeot:2008', 'P24 (Mk2)', 'p24', 2019, null, 'B-SUV de diseño e interior i-Cockpit; gama PureTech, BlueHDi y la variante eléctrica e-2008.', 'La segunda generación del 2008 sobre plataforma CMP comparte base con 208, Corsa y Mokka. Motores 1.2 PureTech gasolina, 1.5 BlueHDi diésel y eléctrico. Aplican las cautelas del PureTech con la correa en las series iniciales.', 'B-SUV con gancho visual. El 1.5 BlueHDi con historial es la opción más tranquila; con PureTech, verificar la correa.', '{"Diseño exterior e interior atractivos","Buen maletero para el segmento","Opción eléctrica e-2008"}'::text[], '{"Correa de distribución ''húmeda'' del 1.2 PureTech (series iniciales)","Sistema AdBlue en el BlueHDi","Ergonomía del i-Cockpit no gusta a todos"}'::text[], '[{"q":"¿El 2008 Mk2 comparte mecánica con el 208?","a":"Sí, plataforma CMP y toda la gama de motores, incluida la versión eléctrica."},{"q":"¿El PureTech del 2008 tiene el problema de la correa?","a":"Las unidades iniciales sí; conviene verificar el estado y el historial de la correa bañada en aceite."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4300, 434),
  ('peugeot:5008:p87', 'peugeot:5008', 'P87 (Mk2)', 'p87', 2017, 2024, 'SUV de 7 plazas con maletero gigante: el hermano grande del 3008, con las mismas mecánicas PSA.', 'La segunda generación del 5008 dejó de ser monovolumen para convertirse en SUV de 7 plazas sobre plataforma EMP2, compartida con el 3008. Motores 1.2/1.6 PureTech y 1.5/2.0 BlueHDi. Tercera fila con asientos extraíbles.', 'SUV familiar de 7 plazas racional. El 1.5/2.0 BlueHDi para quien hace kilómetros; revisar la correa si es PureTech.', '{"Maletero enorme y modularidad de la tercera fila","Interior vistoso y bien equipado","BlueHDi 2.0 con buena reputación"}'::text[], '{"Correa ''húmeda'' del PureTech en series iniciales","Sistema AdBlue en los diésel","Tercera fila justa para adultos en viaje largo"}'::text[], '[{"q":"¿El 5008 Mk2 es un 3008 con 7 plazas?","a":"Comparten plataforma y motores; el 5008 es más largo y añade una tercera fila de asientos extraíbles."},{"q":"¿Qué motor del 5008 es más fiable?","a":"El BlueHDi 2.0 tiene muy buena reputación; el 1.5 BlueHDi también, cuidando el AdBlue."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV 7 plazas', 4641, 780),
  ('peugeot:508:r8', 'peugeot:508', 'R8 (Mk2)', 'r8', 2018, null, 'Berlina de diseño con portón trasero: imagen premium, i-Cockpit y gama PureTech, BlueHDi e híbrido enchufable.', 'La segunda generación del 508 apostó por una carrocería fastback más baja y deportiva. Motores 1.6 PureTech, 1.5/2.0 BlueHDi y el híbrido enchufable Hybrid. El SW familiar mantiene la línea. Aplican las cautelas habituales de PSA (correa PureTech, AdBlue).', 'Berlina con personalidad. El 2.0 BlueHDi para kilómetros; el Hybrid solo si lo enchufas.', '{"Diseño exterior muy logrado","Buen equipamiento tecnológico","BlueHDi 2.0 sobrio en viaje"}'::text[], '{"Correa ''húmeda'' del 1.6 PureTech en series iniciales","Ergonomía del i-Cockpit y visibilidad trasera","Hybrid: maletero y precio penalizados si no se carga"}'::text[], '[{"q":"¿El 508 Mk2 es una berlina o un fastback?","a":"Es una berlina con portón trasero y línea de fastback; combina estética de coupé con la practicidad de un portón."},{"q":"¿Qué autonomía tiene el 508 Hybrid?","a":"Homologa en torno a 50-55 km eléctricos WLTP; en uso real algo menos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina fastback y SW', 4750, 487),
  ('renault:kadjar:ha', 'renault:kadjar', 'HA / HL', 'ha', 2015, 2022, 'SUV compacto hermano del Qashqai J11: 1.5 dCi sobrio, 1.3 TCe moderno y buen espacio interior.', 'El Renault Kadjar comparte plataforma CMF con el Qashqai J11. Motores 1.5/1.6 dCi diésel y 1.2/1.3 TCe gasolina. El restyling de 2019 estrenó el 1.3 TCe y mejoró el interior. Aplican las cautelas del 1.2 TCe (consumo de aceite) en las primeras series.', 'SUV familiar racional. El 1.5 dCi con caja manual es la compra más tranquila; el 1.3 TCe del restyling, la opción gasolina.', '{"Buen espacio interior y maletero","1.5 dCi muy sobrio","Confort de suspensión"}'::text[], '{"Consumo de aceite del 1.2 TCe (2015-2018)","Caja automática EDC: tirones a baja velocidad","Turbo y volante bimasa del dCi con kilómetros"}'::text[], '[{"q":"¿El Kadjar es un Qashqai francés?","a":"Comparten plataforma y motores con el Qashqai J11; cambian diseño, equipamiento y ajuste de suspensión."},{"q":"¿Qué motor del Kadjar comprar?","a":"El 1.5 dCi para carretera; en gasolina, el 1.3 TCe del restyling de 2019 antes que el 1.2 TCe inicial."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4489, 472),
  ('renault:scenic:j9', 'renault:scenic', 'IV (J9)', 'j9', 2016, 2022, 'Monovolumen con estética de crossover y ruedas grandes: práctico, cómodo y con el 1.5 dCi de siempre.', 'La cuarta generación del Scénic adoptó ruedas de 20 pulgadas de serie y una imagen más SUV. Motores 1.2/1.3 TCe gasolina y 1.5/1.7 dCi diésel, además del Grand Scénic de 7 plazas. Confort de marcha bueno; revisar la caja EDC.', 'Monovolumen cómodo y práctico. El 1.5 dCi para kilómetros; el Grand Scénic si necesitas 7 plazas.', '{"Confort de suspensión por encima de la media","Habitabilidad y modularidad","1.5 dCi sobrio"}'::text[], '{"Consumo de aceite del 1.2 TCe en primeras series","Neumáticos de 20\" caros de reemplazar","Caja EDC de doble embrague en uso urbano"}'::text[], '[{"q":"¿El Scénic IV es un monovolumen o un SUV?","a":"Es un monovolumen con estética de crossover: ruedas grandes e imagen SUV, pero carrocería y altura de monovolumen."},{"q":"¿El Grand Scénic tiene 7 plazas de verdad?","a":"Sí, con una tercera fila usable para niños o trayectos cortos, típica del segmento."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Monovolumen', 4406, 506),
  ('renault:twingo:iii', 'renault:twingo', 'III', 'iii', 2014, 2023, 'Urbano con motor trasero y giro cortísimo: ágil como pocos en ciudad, con maletero mínimo.', 'La tercera generación del Twingo, desarrollada con Smart, coloca el motor detrás y bajo el maletero. Eso da un radio de giro excepcional y buena habitabilidad delantera. Motores 1.0 SCe atmosférico y 0.9 TCe turbo. Poco maletero y acceso a la mecánica más complejo.', 'El urbano más ágil de aparcar. El 0.9 TCe para algo de brío; el 1.0 SCe basta para ciudad pura.', '{"Radio de giro y agilidad urbana excepcionales","Buena habitabilidad delantera para el tamaño","Diseño simpático"}'::text[], '{"Maletero mínimo y sin apenas hueco delantero","Acceso a la mecánica trasera más costoso en taller","1.0 SCe justo en cuesta y en autovía"}'::text[], '[{"q":"¿Por qué el Twingo III lleva el motor detrás?","a":"Se desarrolló junto al Smart ForFour; el motor trasero permite un giro muy cerrado y ruedas delanteras que giran mucho."},{"q":"¿Sirve para carretera?","a":"Para tramos cortos; en autovía es ruidoso y el 1.0 atmosférico va escaso, sobre todo cargado."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Urbano 5 puertas', 3595, 188),
  ('renault:austral:1', 'renault:austral', '1ª gen', '1', 2022, null, 'El sustituto del Kadjar: SUV compacto con híbrido E-Tech eficiente y micro-hibridación de 48 V.', 'El Renault Austral sustituye al Kadjar sobre la plataforma CMF-CD. La gama se centra en el híbrido E-Tech full hybrid (200 CV) y el mild-hybrid de 48 V, con el 1.2 TCe de base. Interior muy tecnológico con pantalla vertical.', 'SUV compacto moderno. El E-Tech híbrido para consumo urbano bajo; el mild-hybrid como opción más asequible.', '{"Híbrido E-Tech eficiente en ciudad","Interior tecnológico y bien acabado","Buen espacio y maletero"}'::text[], '{"Modelo reciente: historial de fiabilidad todavía corto","Caja multimodo del E-Tech: tacto peculiar","Precio de ocasión aún alto"}'::text[], '[{"q":"¿El Austral sustituye al Kadjar?","a":"Sí, es su relevo directo, con plataforma nueva y foco en la hibridación."},{"q":"¿Hay Austral diésel?","a":"No, la gama se basa en gasolina: 1.2 TCe mild-hybrid de 48 V y el híbrido E-Tech."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4510, 500),
  ('dacia:jogger:1', 'dacia:jogger', '1ª gen', '1', 2021, null, 'Familiar de 7 plazas al precio de un utilitario: mucho espacio, poco lujo y mecánica probada del grupo Renault.', 'El Dacia Jogger combina carrocería de familiar alargado con 7 plazas. Motores TCe 1.0 gasolina, ECO-G GLP y el híbrido 1.6 (Hybrid 140). Las plazas de la tercera fila son extraíbles. Coche honesto y funcional.', 'La forma más barata de mover a 7 personas. TCe/GLP para minimizar coste, híbrido para uso urbano.', '{"7 plazas a precio de utilitario","Maletero enorme con 5 plazas","Mecánica del grupo Renault probada"}'::text[], '{"Materiales e insonorización básicos","TCe 1.0 justo con el coche lleno","Equipamiento de asistencias limitado en acabados bajos"}'::text[], '[{"q":"¿El Jogger tiene 7 plazas de serie?","a":"Depende del acabado; la tercera fila es opcional en las versiones de acceso y extraíble."},{"q":"¿Diésel o gasolina en el Jogger?","a":"No hay diésel: TCe 1.0 gasolina, ECO-G GLP (el más barato de usar) e híbrido 1.6."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Familiar 7 plazas', 4547, 607),
  ('dacia:logan:iii', 'dacia:logan', 'III', 'iii', 2020, null, 'Berlina económica con maletero enorme: plataforma moderna del Clio y mecánica sencilla.', 'La tercera generación del Logan adopta la plataforma CMF-B del Clio, con un salto de seguridad y comportamiento. Motores TCe 1.0 gasolina y ECO-G GLP. Maletero de 528 litros y precio mínimo.', 'La berlina más barata del mercado. ECO-G GLP para minimizar el gasto por kilómetro.', '{"Precio de compra y mantenimiento mínimos","Maletero enorme","Plataforma moderna compartida con Clio"}'::text[], '{"Materiales e insonorización básicos","TCe 1.0 justo con carga","Equipamiento de asistencias limitado en acabados bajos"}'::text[], '[{"q":"¿El Logan III comparte plataforma con el Clio?","a":"Sí, usa la plataforma CMF-B, lo que mejora mucho la seguridad y el comportamiento frente al Logan anterior."},{"q":"¿Cuánto maletero tiene?","a":"En torno a 528 litros, muy por encima de la media de las berlinas compactas."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina', 4359, 528),
  ('ford:kuga:mk3', 'ford:kuga', 'Mk3', 'mk3', 2019, null, 'SUV familiar que se conduce bien: gama amplia con 1.5 EcoBoost, 1.5 EcoBlue, híbrido e híbrido enchufable.', 'La tercera generación del Kuga sobre plataforma C2 ofrece una de las gamas más completas del segmento: 1.5 EcoBoost gasolina, 1.5/2.0 EcoBlue diésel, híbrido (FHEV) e híbrido enchufable (PHEV). Buen comportamiento dinámico. Revisar la correa ''húmeda'' del EcoBlue.', 'SUV familiar equilibrado. El 1.5 EcoBlue para kilómetros, el híbrido para uso urbano-mixto, el PHEV solo si cargas.', '{"Comportamiento dinámico por encima de la media","Gama de motores muy completa","Buen espacio y maletero (con banqueta deslizante)"}'::text[], '{"Correa de distribución ''húmeda'' del 1.5 EcoBlue (intervalo estricto)","PHEV: hubo campañas por la batería en las primeras unidades","Multimedia SYNC 3 algo desfasada en primeras series"}'::text[], '[{"q":"¿El Kuga PHEV tuvo problemas?","a":"Las primeras unidades tuvieron una campaña por riesgo de sobrecalentamiento de la batería; conviene verificar que la unidad esté actualizada."},{"q":"¿Qué maletero tiene el Kuga Mk3?","a":"Entre 435 y 580 litros según la posición de la banqueta trasera deslizante (menos en las versiones electrificadas)."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4614, 475),
  ('ford:mondeo:mk5', 'ford:mondeo', 'Mk5 (CD391)', 'mk5', 2014, 2022, 'Berlina grande de ocasión muy barata: mucho coche por el dinero, con el 2.0 TDCi y el híbrido HEV.', 'La última generación del Mondeo en Europa. Motores 1.5/2.0 EcoBoost gasolina, 1.5/2.0 TDCi diésel y una versión híbrida (solo berlina). Espacio y confort de categoría superior a precio de ganga en el usado. Revisar la caja Powershift en los diésel automáticos.', 'Mucha berlina por poco dinero. El 2.0 TDCi manual es la compra más tranquila; el híbrido para uso urbano.', '{"Espacio y confort de clase superior","Precio de ocasión muy bajo","Sportbreak con maletero enorme"}'::text[], '{"Caja automática Powershift de doble embrague (tirones, campañas)","EGR y turbo del 2.0 TDCi con kilómetros","Consumo alto del híbrido en autovía"}'::text[], '[{"q":"¿El Mondeo Mk5 híbrido se enchufa?","a":"No, es un híbrido autorrecargable; solo está disponible en carrocería berlina."},{"q":"¿La caja automática del Mondeo diésel es fiable?","a":"La Powershift de doble embrague dio tirones y desgaste en muchas unidades. Si puedes, elige el manual o revisa el historial de campañas."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina, Sportbreak y híbrido', 4871, 500),
  ('hyundai:i20:bc3', 'hyundai:i20', 'BC3', 'bc3', 2020, null, 'Utilitario racional con garantía de 5 años: 1.0 T-GDi con o sin 48 V y buen maletero para el segmento.', 'La tercera generación del i20 sobre plataforma K2. Motores 1.0 T-GDi (con opción mild-hybrid de 48 V) y 1.2 atmosférico. Buen maletero y habitabilidad, y el respaldo de la garantía de fábrica de 5 años.', 'Utilitario de bajo riesgo con el 1.0 T-GDi 100. La garantía larga es un plus en el usado reciente.', '{"Garantía de fábrica de 5 años","Buen maletero y habitabilidad","1.0 T-GDi elástico"}'::text[], '{"Carbonilla en admisión del T-GDi en uso solo urbano","1.2 atmosférico justo de fuerza","Multimedia básica en acabados de acceso"}'::text[], '[{"q":"¿El i20 mantiene la garantía si lo compro usado?","a":"Sí, la garantía de 5 años de Hyundai es de fábrica y se transfiere al nuevo propietario mientras esté vigente y con las revisiones al día."},{"q":"¿1.0 T-GDi o 1.2 atmosférico?","a":"El 1.0 T-GDi turbo es claramente preferible salvo que el uso sea urbano puro y el precio del atmosférico sea muy inferior."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4040, 352),
  ('hyundai:kona:os', 'hyundai:kona', 'OS', 'os', 2017, 2023, 'B-SUV con gama muy completa: gasolina 1.0/1.6 T-GDi, diésel 1.6 CRDi, híbrido y eléctrico con buena autonomía.', 'La primera generación del Kona ofreció desde muy pronto versión eléctrica con autonomía real alta para su época. Motores 1.0/1.6 T-GDi gasolina, 1.6 CRDi diésel, híbrido 1.6 y eléctrico. Garantía de 5 años. Revisar la caja DCT de doble embrague.', 'B-SUV muy versátil. El 1.0 T-GDi para ciudad, el híbrido para uso mixto, el eléctrico si te cuadra la autonomía.', '{"Gama de motores muy amplia, incluido eléctrico","Garantía de fábrica de 5 años","Buen equipamiento de serie"}'::text[], '{"Caja DCT de doble embrague: tacto en maniobras y en frío","Maletero justo en las versiones no eléctricas","Kona EV: campañas de batería en unidades 2018-2020"}'::text[], '[{"q":"¿El Kona eléctrico tuvo problemas de batería?","a":"Hubo una campaña mundial en unidades 2018-2020 por riesgo de incendio de la batería; conviene verificar que la unidad tenga la actualización o la batería sustituida."},{"q":"¿Qué autonomía tiene el Kona EV de 64 kWh?","a":"Homologa en torno a 449 km WLTP; en uso real y con frío, bastante menos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4165, 361),
  ('kia:niro:de', 'kia:niro', 'DE', 'de', 2016, 2022, 'SUV compacto solo electrificado: híbrido, híbrido enchufable y eléctrico, con 7 años de garantía Kia.', 'La primera generación del Niro nació sin motor de combustión puro: híbrido 1.6 GDi, híbrido enchufable y eléctrico (e-Niro) con buena autonomía. A diferencia de Toyota, el híbrido usa una caja automática de doble embrague convencional. Garantía de 7 años.', 'SUV electrificado racional con la garantía más larga del mercado. El híbrido para uso mixto; el e-Niro si te cuadra la autonomía.', '{"Garantía de fábrica de 7 años","Conducción ''normal'' con caja DCT (no e-CVT)","e-Niro con buena autonomía real"}'::text[], '{"Caja DCT de doble embrague: tacto en maniobras","Consumo del híbrido algo mayor que un Toyota en ciudad","Maletero reducido en la versión enchufable"}'::text[], '[{"q":"¿El Niro híbrido se conduce como un Toyota?","a":"No exactamente: usa una caja automática de doble embrague de 6 marchas, con cambios perceptibles, en vez del e-CVT de Toyota."},{"q":"¿La garantía de 7 años se transfiere?","a":"Sí, es de fábrica y ligada al coche mientras esté vigente y con las revisiones al día."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4375, 427),
  ('kia:picanto:ja', 'kia:picanto', 'JA', 'ja', 2017, null, 'Urbano con maletero de récord en su clase y 7 años de garantía: 1.0 y 1.25 atmosféricos, sencillos y fiables.', 'La tercera generación del Picanto ofrece uno de los maleteros más grandes del segmento A. Motores 1.0 y 1.25 atmosféricos y un 1.0 T-GDi turbo. Mecánica sencilla, barata de mantener y con la garantía de 7 años de Kia.', 'De los mejores urbanos por practicidad y garantía. El 1.25 atmosférico basta para ciudad; el 1.0 T-GDi si sales a carretera.', '{"Maletero de referencia en el segmento A","Garantía de fábrica de 7 años","Mecánica atmosférica sencilla y fiable"}'::text[], '{"Atmosféricos justos de fuerza en autovía y cargados","Insonorización básica","Equipamiento de seguridad limitado en acabados de acceso"}'::text[], '[{"q":"¿Cuánto maletero tiene el Picanto JA?","a":"En torno a 255 litros, de los mayores del segmento de urbanos."},{"q":"¿Qué motor del Picanto comprar?","a":"El 1.25 atmosférico para uso urbano; el 1.0 T-GDi turbo si haces carretera con frecuencia."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Urbano 5 puertas', 3595, 255),
  ('kia:rio:yb', 'kia:rio', 'YB', 'yb', 2017, null, 'Utilitario racional con 7 años de garantía: 1.0 T-GDi con o sin 48 V y 1.2 atmosférico.', 'La cuarta generación del Rio comparte base con el Hyundai i20 de su época. Motores 1.0 T-GDi (con opción mild-hybrid de 48 V), 1.2 y 1.4 atmosféricos. Buen maletero y el respaldo de la garantía de 7 años.', 'Utilitario de bajo riesgo con el 1.0 T-GDi 100 y la garantía más larga del segmento.', '{"Garantía de fábrica de 7 años","Buen maletero y habitabilidad","1.0 T-GDi elástico"}'::text[], '{"Carbonilla en admisión del T-GDi en uso solo urbano","Atmosféricos justos de fuerza","Multimedia básica en acabados de acceso"}'::text[], '[{"q":"¿El Rio YB es un i20 con emblema Kia?","a":"Comparten plataforma y motores de su generación; cambian diseño, equipamiento y la garantía (7 años Kia)."},{"q":"¿Merece la pena el mild-hybrid de 48 V?","a":"Suaviza el Start&Stop y reduce algo el consumo urbano; el ahorro real es modesto."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4065, 325),
  ('kia:stonic:yb', 'kia:stonic', 'YB', 'yb', 2017, null, 'B-SUV sobre base del Rio: 1.0 T-GDi ágil, buen maletero y 7 años de garantía Kia.', 'El Kia Stonic comparte plataforma con el Rio YB. Motores 1.0 T-GDi (con opción 48 V), 1.2 atmosférico y, en su día, 1.6 CRDi diésel. B-SUV racional con buen maletero y la garantía de 7 años.', 'B-SUV racional con el 1.0 T-GDi 100 y la garantía más larga del segmento.', '{"Garantía de fábrica de 7 años","1.0 T-GDi elástico y sobrio","Buen maletero para el segmento"}'::text[], '{"Carbonilla en admisión del T-GDi en uso solo urbano","1.2 atmosférico justo de fuerza","Plásticos duros en acabados de acceso"}'::text[], '[{"q":"¿El Stonic es un Rio más alto?","a":"Comparte plataforma y motores con el Rio; añade carrocería SUV y algo más de altura libre."},{"q":"¿Hay Stonic diésel?","a":"Las primeras series ofrecieron el 1.6 CRDi; después la gama se centró en el 1.0 T-GDi y el 1.2 atmosférico."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4140, 352),
  ('opel:corsa:f', 'opel:corsa', 'F', 'f', 2019, null, 'El primer Corsa de la era Stellantis: gemelo del Peugeot 208, con PureTech, BlueHDi y el eléctrico Corsa-e.', 'La sexta generación del Corsa pasó a la plataforma CMP de PSA y comparte casi todo con el Peugeot 208. Motores 1.2 PureTech gasolina, 1.5 BlueHDi diésel y eléctrico. Aplican las mismas cautelas del PureTech con la correa en las series iniciales.', 'Utilitario racional. El 1.2 PureTech (verificando correa) o el eléctrico Corsa-e para ciudad; el 1.5 BlueHDi para kilómetros.', '{"Base moderna compartida con el 208","Opción eléctrica Corsa-e","Buen equipamiento de seguridad en versiones recientes"}'::text[], '{"Correa de distribución ''húmeda'' del 1.2 PureTech (series iniciales)","Sistema AdBlue en el BlueHDi","Plásticos interiores duros"}'::text[], '[{"q":"¿El Corsa F es un Peugeot 208 con otro emblema?","a":"Comparten plataforma CMP, motores y buena parte de las piezas; cambian diseño, interior y ajuste."},{"q":"¿El PureTech del Corsa F tiene el problema de la correa?","a":"Las unidades iniciales sí; conviene verificar el estado y el historial de la correa bañada en aceite."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 4060, 309),
  ('opel:astra:k', 'opel:astra', 'K', 'k', 2015, 2021, 'El último Astra de la era GM: ligero, ágil y con el 1.6 CDTi ''whisper diesel'' propio de Opel.', 'La generación K del Astra (todavía sobre plataforma GM) destacó por su bajo peso y buen comportamiento. Motores 1.0/1.4 Turbo gasolina y 1.6 CDTi diésel propio de Opel. El Sports Tourer familiar tiene buen maletero. Vigilar EGR/DPF de los diésel y la bomba de agua de los gasolina.', 'Compacto ágil y barato de ocasión. El 1.6 CDTi para kilómetros; el 1.4 Turbo para uso mixto.', '{"Bajo peso y comportamiento ágil","1.6 CDTi silencioso para su clase","Precio de ocasión contenido"}'::text[], '{"EGR y DPF de los diésel en uso urbano","Consumo de aceite y bomba de agua en algún 1.4 Turbo","Multimedia IntelliLink básica en acabados de acceso"}'::text[], '[{"q":"¿El Astra K es de la era Opel-GM u Opel-PSA?","a":"Es de la era GM; el Astra L posterior (2021) ya usa plataforma PSA/Stellantis."},{"q":"¿El 1.6 CDTi del Astra K es fiable?","a":"Con mantenimiento correcto es sobrio y silencioso; el punto a vigilar es el sistema de gases (EGR/DPF) en coches muy urbanos."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Compacto 5 puertas y Sports Tourer', 4370, 370),
  ('opel:mokka:b', 'opel:mokka', 'B', 'b', 2020, null, 'B-SUV de diseño rompedor sobre plataforma Stellantis: PureTech, BlueHDi y el eléctrico Mokka-e.', 'La segunda generación del Mokka estrenó el lenguaje de diseño ''Vizor'' de Opel sobre la plataforma CMP/e-CMP de Stellantis. Motores 1.2 PureTech, 1.5 BlueHDi y eléctrico. Comparte casi todo con Peugeot 2008 y Citroën C3 Aircross.', 'B-SUV con imagen fuerte. El 1.2 PureTech (verificando correa) para ciudad; el 1.5 BlueHDi para kilómetros.', '{"Diseño exterior diferenciado","Base moderna compartida con Peugeot/Citroën","Opción eléctrica Mokka-e"}'::text[], '{"Correa ''húmeda'' del 1.2 PureTech en series iniciales","Maletero justo para el segmento","Plásticos interiores duros"}'::text[], '[{"q":"¿El Mokka B comparte mecánica con el Peugeot 2008?","a":"Sí, plataforma CMP y toda la gama de motores, incluida la versión eléctrica."},{"q":"¿El Mokka B es fiable?","a":"La base mecánica es la del grupo Stellantis; el punto a vigilar es la correa del PureTech en las primeras unidades."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4151, 350),
  ('opel:crossland:p2qo', 'opel:crossland', 'P2QO', 'p2qo', 2017, 2024, 'B-SUV práctico y familiar sobre plataforma PSA: banqueta trasera deslizante y buen maletero.', 'El Opel Crossland (Crossland X hasta 2020) comparte plataforma CMP con Peugeot 2008 y Citroën C3 Aircross. Motores 1.2 PureTech gasolina y 1.5 BlueHDi diésel. Banqueta trasera deslizante para priorizar espacio o maletero.', 'B-SUV racional y práctico. El 1.2 PureTech (verificando correa) para ciudad; el 1.5 BlueHDi para kilómetros.', '{"Modularidad de la banqueta trasera deslizante","Buen maletero para el segmento","Mecánicas PSA conocidas"}'::text[], '{"Correa ''húmeda'' del 1.2 PureTech en series iniciales","Comportamiento más de monovolumen que de SUV","Multimedia básica en acabados de acceso"}'::text[], '[{"q":"¿El Crossland es un SUV o un monovolumen alto?","a":"Es un B-SUV con enfoque práctico: altura y modularidad de monovolumen, sin pretensiones de campo."},{"q":"¿Comparte mecánica con el Citroën C3 Aircross?","a":"Sí, plataforma y motores del grupo PSA/Stellantis."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4212, 410),
  ('opel:grandland:a18', 'opel:grandland', 'A18', 'a18', 2017, 2024, 'SUV compacto hermano del Peugeot 3008: PureTech, BlueHDi e híbrido enchufable Hybrid4 con tracción total.', 'El Opel Grandland (Grandland X hasta 2021) comparte plataforma EMP2 con el Peugeot 3008 y el Citroën C5 Aircross. Motores 1.2/1.6 PureTech, 1.5/2.0 BlueHDi e híbrido enchufable, este último con tracción total en la versión Hybrid4.', 'SUV familiar racional. El 1.5 BlueHDi con historial es la opción más tranquila; con PureTech, verificar la correa.', '{"Buen espacio y maletero","Mecánicas compartidas con el 3008, conocidas","BlueHDi 2.0 con buena reputación"}'::text[], '{"Correa ''húmeda'' del PureTech en series iniciales","Sistema AdBlue en los diésel","Hybrid4: coste de mantenimiento y batería"}'::text[], '[{"q":"¿El Grandland es un Peugeot 3008 de Opel?","a":"Comparten plataforma y motores; cambian diseño, interior y ajuste de suspensión."},{"q":"¿El Grandland Hybrid4 tiene tracción total?","a":"Sí, añade un motor eléctrico en el eje trasero que le da tracción total en determinadas condiciones."}]'::jsonb, 'published', 'demo', '2026-09-01', 'SUV', 4477, 514),
  ('opel:insignia:b', 'opel:insignia', 'B (Z18)', 'b', 2017, 2022, 'Berlina grande de ocasión muy barata: mucho espacio y confort, con el 1.6/2.0 CDTi y la tracción total opcional.', 'La segunda generación del Insignia (era GM) creció en tamaño y bajó de peso. Motores 1.5/2.0 Turbo gasolina y 1.6/2.0 CDTi diésel, con opción de tracción total. El Sports Tourer tiene un maletero enorme. Vigilar EGR/DPF de los diésel.', 'Mucha berlina por muy poco dinero. El 1.6 CDTi para uso sensato; el 2.0 CDTi para viaje y carga.', '{"Espacio y confort de categoría superior","Precio de ocasión muy bajo","Sports Tourer con maletero enorme"}'::text[], '{"EGR y DPF de los diésel en uso urbano","Coste de mantenimiento de la tracción total","Multimedia y asistencias básicas en acabados de acceso"}'::text[], '[{"q":"¿El Insignia B es de Opel-GM o de Stellantis?","a":"Es de la era GM. No hubo una tercera generación: el Insignia se descatalogó tras la B."},{"q":"¿Qué diésel del Insignia B comprar?","a":"El 1.6 CDTi para uso mixto y el 2.0 CDTi (a veces con tracción total) para viaje y carga; ambos, cuidando el sistema de gases."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Berlina Grand Sport y Sports Tourer', 4897, 490),
  ('citroen:c3:iii', 'citroen:c3', 'III (SX/SW)', 'iii', 2016, null, 'Utilitario cómodo y con personalidad: suspensión blanda, asientos mullidos y la cámara ConnectedCAM.', 'La tercera generación del C3 apostó por el confort y el diseño personalizable (Airbump). Motores 1.2 PureTech gasolina y 1.5/1.6 BlueHDi diésel. Comodidad por encima de la media del segmento; a cambio, comportamiento más blando. Aplican las cautelas del PureTech con la correa.', 'Utilitario para quien prioriza confort. El 1.2 PureTech (verificando correa) para ciudad; el BlueHDi para kilómetros.', '{"Confort de suspensión y asientos por encima de la media","Diseño personalizable","Buen consumo del BlueHDi"}'::text[], '{"Correa ''húmeda'' del 1.2 PureTech en series iniciales","Comportamiento blando y balanceo en curva","Multimedia lenta en acabados de acceso"}'::text[], '[{"q":"¿El C3 III es cómodo?","a":"Sí, es de los utilitarios más confortables del segmento en amortiguación y asientos; a cambio balancea más en curva."},{"q":"¿El PureTech del C3 tiene el problema de la correa?","a":"Las unidades 2016-2021 sí; conviene verificar el estado y el historial de la correa bañada en aceite."}]'::jsonb, 'published', 'demo', '2026-09-01', 'Utilitario 5 puertas', 3996, 300),
