insert into known_issues (id, engine_id, generation_id, title, symptoms, cause, severity, mileage_min, mileage_max, cost_min, cost_max, confidence, status) values
  ('issue-b47-cadena', 'b47d20', null, 'Desgaste de la cadena de distribución (parte trasera del motor)', 'Ruido metálico o ''sonajero'' en el arranque en frío que dura unos segundos; en casos avanzados, tintineo constante y códigos de sincronización de árbol de levas.', 'Tensor y guías de la cadena de distribución con desgaste prematuro en parte de la producción, agravado por cambios de aceite espaciados o aceite inadecuado.', 'alta', 120000, 220000, 900, 2200, 'moderada', 'published'),
  ('issue-b47-egr', 'b47d20', null, 'Fallo o atasco de la válvula EGR / refrigerador de gases', 'Pérdida de potencia, modo emergencia, testigo de motor encendido y, en casos graves, riesgo de sobrecalentamiento localizado.', 'Acumulación de carbonilla y grietas en el refrigerador de EGR; problema tratado con campañas y piezas revisadas en varios mercados.', 'media', 90000, 180000, 350, 900, 'solida', 'published'),
  ('issue-b48-bomba-agua', 'b48', null, 'Fugas por la bomba de agua eléctrica y junta de la tapa de balancines', 'Nivel de refrigerante bajando lentamente, olor dulce en caliente, manchas en el bajo motor; con la junta, consumo de aceite y humo puntual.', 'Bomba de agua eléctrica con vida útil limitada y juntas que endurecen con los ciclos térmicos.', 'media', 80000, 160000, 300, 700, 'moderada', 'published'),
  ('issue-puretech-correa', 'puretech-1-2', null, 'Degradación de la correa de distribución ''húmeda'' (series 2019-2021)', 'Ruido de rodadura o silbido del cárter, testigo de presión de aceite, restos de goma en el filtro y en el colador de la bomba de aceite; en el peor caso, rotura y daño de válvulas.', 'La correa de distribución trabaja sumergida en aceite y su recubrimiento se deshace antes de tiempo, soltando partículas que obstruyen el circuito de lubricación.', 'alta', 60000, 150000, 700, 2500, 'solida', 'published'),
  ('issue-puretech-carbonilla', 'puretech-1-2', null, 'Carbonilla en válvulas de admisión con uso urbano', 'Ralentí irregular, tirones a baja carga, ligero aumento de consumo tras muchos kilómetros de ciudad.', 'Inyección directa sin lavado de las válvulas de admisión; se acentúa con trayectos cortos y aceite de baja calidad.', 'baja', 90000, null, 200, 500, 'moderada', 'published'),
  ('issue-tce13-aceite', 'tce-1-3', null, 'Consumo elevado de aceite y desgaste de camisas en primeras series', 'Necesidad de rellenar aceite entre revisiones, humo azulado en aceleraciones fuertes tras retención, tirones en frío.', 'Lotes iniciales (aprox. 2018-2020) con tratamiento de camisas y segmentos por debajo de tolerancia; corregido en producción posterior y con campañas.', 'media', 30000, 120000, 0, 3000, 'moderada', 'published'),
  ('issue-dci15-turbo', 'dci-1-5-blue', null, 'Desgaste del turbo y del volante bimasa con muchos kilómetros', 'Silbido agudo creciente, pérdida de empuje, humo; en el volante, traqueteo al ralentí y vibración al soltar el embrague.', 'Componentes de desgaste normal en un motor de alto kilometraje; se adelanta con aceite sucio o conducción muy exigente en frío.', 'media', 150000, 250000, 600, 1600, 'moderada', 'published'),
  ('issue-ea288-egr-adblue', 'ea288-2-0-tdi', null, 'Averías del sistema AdBlue / SCR y de la EGR', 'Aviso de ''arranque no posible en X km'', testigo de motor, entrada en modo taller; con la EGR, humo y pérdida de potencia.', 'Sensores de NOx, bomba e inyector de AdBlue sensibles; EGR con carbonilla en uso urbano.', 'media', 90000, 180000, 300, 1200, 'solida', 'published'),
  ('issue-15tsi-tirones', 'ea211-1-5-tsi', null, 'Tirones y vacilaciones a baja carga en primeras series', 'Sensación de ''ahogo'' o microcortes al circular suave a pocas revoluciones, sobre todo en frío.', 'Mapa de gestión demasiado agresivo con el corte de cilindros y el EGR; resuelto en gran medida por actualización de software.', 'baja', 0, null, 0, 120, 'solida', 'published'),
  ('issue-ecoboost-refrigeracion', 'ecoboost-1-0', null, 'Fallos de refrigeración en series antiguas (tubo de degas)', 'Pérdida de refrigerante sin fuga visible, calentón, en casos graves fisura de culata.', 'Conducto de refrigeración de plástico y diseño del circuito en versiones 2012-2017; mitigado en el Focus/Fiesta recientes y en las versiones mHEV.', 'alta', 60000, 160000, 400, 3000, 'moderada', 'published'),
  ('issue-dsg-dq200', null, 'volkswagen:golf:mk7', 'Desgaste de la mecatrónica de la caja DSG seca (DQ200)', 'Tirones al arrancar, retención al soltar freno, entradas de marcha bruscas, testigo de caja.', 'Módulo mecatrónico y embragues secos sensibles al uso urbano intensivo y a atascos frecuentes.', 'media', 90000, 180000, 700, 1800, 'moderada', 'published'),
  ('issue-golf8-software', null, 'volkswagen:golf:mk8', 'Fallos de infoentretenimiento y conectividad (2020-2021)', 'Reinicios de la pantalla central, cámara de visión trasera que no carga, fallos de Car-Net/actualizaciones OTA, congelaciones.', 'Software inmaduro en el lanzamiento del sistema MIB3; corregido de forma progresiva con actualizaciones en taller y OTA.', 'baja', 0, null, 0, 200, 'solida', 'published'),
  ('issue-w177-7gdct', null, 'mercedes-benz:clase-a:w177', 'Tirones de la caja 7G-DCT de doble embrague en frío y maniobras', 'Retenciones y ''saltos'' al aparcar, respuesta perezosa al reanudar la marcha, ruido de embragues en frío.', 'Comportamiento propio de la caja de doble embrague seca; se atenúa con adaptaciones y software actualizado.', 'baja', 0, 120000, 0, 400, 'moderada', 'published'),
  ('issue-g30-neumatica', null, 'bmw:serie-5:g30', 'Fallo de la suspensión neumática trasera (si la equipa)', 'Trasera hundida tras aparcar, compresor trabajando en exceso, aviso de suspensión, marcha dura.', 'Fugas en fuelles neumáticos y desgaste del compresor con los años y el frío.', 'media', 100000, 200000, 400, 1400, 'moderada', 'published'),
  ('issue-n47-cadena', null, 'bmw:serie-3:f30', 'Cadena de distribución del diésel N47 (unidades 2012-2014)', 'Ruido de cadena en frío por la parte trasera del motor, tintineo bajo carga; riesgo de salto de sincronización si se ignora.', 'Tensor y guías del N47 con desgaste prematuro; los B47 posteriores mejoraron el diseño.', 'alta', 120000, 200000, 1000, 2500, 'moderada', 'published'),
  ('issue-ea111-cadena', 'ea111-1-4-tsi', null, 'Estiramiento de la cadena de distribución', 'Ruido de cadena en arranque en frío, tirón al arrancar, testigo de motor y códigos de correlación de árbol de levas; en el peor caso, salto de sincronización.', 'Tensor y guías de la cadena con desgaste prematuro en la producción 2007-2012, agravado por intervalos de aceite largos.', 'alta', 60000, 150000, 900, 2000, 'solida', 'published'),
  ('issue-ea111-aceite', 'ea111-1-4-tsi', null, 'Consumo elevado de aceite', 'Necesidad de rellenar aceite entre revisiones, humo azulado en aceleraciones tras retención, bujías engrasadas.', 'Desgaste de segmentos y del sistema de ventilación del cárter en parte de la producción.', 'media', 80000, null, 300, 2500, 'moderada', 'published'),
  ('issue-ea211-12tsi-cadena', 'ea211-1-2-tsi', null, 'Cadena de distribución en primeras series (2010-2014)', 'Ruido metálico en frío por la zona de distribución, tirón al arrancar, testigo de motor.', 'Tensor de cadena de primera generación con desgaste prematuro; mejorado en piezas posteriores.', 'media', 60000, 130000, 700, 1500, 'moderada', 'published'),
  ('issue-ea189-emisiones', 'ea189-2-0-tdi', null, 'Software de emisiones (caso ''dieselgate'') y efectos tras la actualización', 'Tras la actualización obligatoria, algunos propietarios reportan más regeneraciones del filtro de partículas, EGR más delicada y, en casos aislados, tirones.', 'El motor formó parte del caso de manipulación de emisiones; la actualización de software cambió la gestión de EGR y postratamiento.', 'media', 90000, 200000, 200, 1200, 'moderada', 'published'),
  ('issue-ea189-16-egr', 'ea189-1-6-tdi', null, 'Averías de EGR y sensores tras la actualización de emisiones', 'Testigo de motor, pérdida de potencia, entrada en modo taller, avisos de sistema anticontaminación.', 'EGR y sensores más solicitados tras el cambio de gestión; se agrava con uso urbano y trayectos cortos.', 'media', 90000, 180000, 250, 900, 'moderada', 'published'),
  ('issue-pd19-colector', 'pd-1-9-tdi', null, 'Rotura de las aletas del colector de admisión (torbellino)', 'Pérdida de potencia, testigo de motor, ruido de traqueteo en el colector; riesgo de que una aleta suelta entre al cilindro.', 'Las aletas de turbulencia del colector de admisión, movidas por un motor eléctrico, se rompen con el tiempo y la carbonilla.', 'alta', 150000, 280000, 250, 700, 'solida', 'published'),
  ('issue-hdi16-turbo', 'hdi-1-6', null, 'Rotura del turbo por obstrucción del circuito de aceite', 'Silbido agudo, humo azulado o negro, pérdida de empuje, testigo de motor.', 'El tubo de engrase del turbo se obstruye con lodos si el aceite no se cambia a tiempo o no es el especificado; el turbo se queda sin lubricación.', 'alta', 90000, 200000, 700, 1800, 'solida', 'published'),
  ('issue-tce12-aceite', 'energy-tce-1-2', null, 'Consumo elevado de aceite y desgaste de segmentos (2013-2018)', 'Rellenos frecuentes de aceite, humo azulado tras retención, en casos graves ralentí irregular y pérdida de compresión.', 'Lotes con tratamiento de segmentos y camisas por debajo de tolerancia; Renault amplió garantías y aplicó campañas en algunos mercados.', 'alta', 40000, 150000, 0, 3500, 'solida', 'published'),
  ('issue-skyd-carbonilla', 'skyactiv-d-2-2', null, 'Carbonilla en admisión y dilución de aceite con uso urbano', 'Pérdida progresiva de respuesta, más regeneraciones del filtro de partículas, nivel de aceite que sube y huele a gasóleo.', 'La baja relación de compresión y las regeneraciones frecuentes en trayectos cortos favorecen la acumulación de carbonilla y la dilución del aceite.', 'media', 60000, 180000, 300, 1500, 'moderada', 'published'),
  ('issue-twinair-aceite', 'twinair-0-9', null, 'Consumo de aceite y consumo real alto', 'Necesidad de rellenar aceite entre revisiones en algunas unidades; consumo de combustible muy por encima del homologado en uso normal.', 'Bicilíndrico turbo muy exigido para mover el coche; el sistema MultiAir y la ventilación del cárter piden aceite exacto y al día.', 'media', 60000, null, 100, 1500, 'moderada', 'published'),
  ('issue-volvo-t-aceite', 'volvo-t3-t4', null, 'Consumo de aceite y cadena de distribución en primeras series', 'Rellenos de aceite entre revisiones, ruido de cadena en frío, testigo de motor en casos avanzados.', 'Segmentos y tensor de cadena de las primeras series Drive-E; Volvo aplicó mejoras y campañas en varios mercados.', 'media', 60000, 160000, 300, 2200, 'moderada', 'published'),
  ('issue-volvo-d-admision', 'volvo-d3-d4', null, 'Carbonilla en el colector de admisión y averías de EGR', 'Pérdida de potencia, testigo de motor, humo, en casos graves modo taller.', 'Acumulación de carbonilla en el colector y en la EGR, acentuada por uso urbano y trayectos cortos.', 'media', 90000, 200000, 300, 1400, 'moderada', 'published'),
  ('issue-honda15t-dilucion', 'honda-1-5-vtec-turbo', null, 'Dilución de gasolina en el aceite (climas fríos, uso urbano)', 'Nivel de aceite que sube, olor a gasolina en la varilla, en casos avanzados testigo de aceite y ralentí irregular.', 'En trayectos cortos con frío, parte de la gasolina no quemada pasa al cárter; afecta sobre todo a unidades 2016-2019. Honda publicó actualizaciones de software.', 'media', 0, 120000, 0, 600, 'solida', 'published'),
  ('issue-opel-cdti-correa', 'opel-1-6-cdti', null, 'Degradación de la correa de distribución y averías de EGR/DPF', 'Restos de goma en el cárter y en el colador de aceite, testigo de presión de aceite; por separado, pérdida de potencia y modo taller por EGR/DPF.', 'La correa de distribución de este motor trabaja en condiciones exigentes; la EGR y el filtro de partículas sufren con el uso urbano.', 'media', 90000, 180000, 400, 1600, 'moderada', 'published'),
  ('issue-b38-carbonilla', 'b38', null, 'Carbonilla en válvulas de admisión con uso urbano', 'Ralentí irregular, ligera pérdida de respuesta y aumento de consumo tras muchos kilómetros de ciudad.', 'Inyección directa sin lavado de las válvulas de admisión; se acentúa con trayectos cortos.', 'baja', 90000, null, 200, 500, 'moderada', 'published'),
  ('issue-b57-egr', 'b57d30', null, 'Fallo del refrigerador de EGR', 'Pérdida de potencia, testigo de motor, y en casos graves riesgo de fugas de refrigerante hacia la admisión.', 'Grietas en el refrigerador de gases de escape; problema tratado con campañas y piezas revisadas en varios mercados.', 'media', 80000, 180000, 400, 1200, 'moderada', 'published'),
  ('issue-puretech-ds-correa', 'puretech-1-2-ds', null, 'Degradación de la correa de distribución ''húmeda'' (series iniciales)', 'Ruido de rodadura o silbido del cárter, testigo de presión de aceite, restos de goma en el filtro de aceite.', 'Misma familia PureTech que el resto del grupo PSA/Stellantis: la correa trabaja sumergida en aceite y puede degradarse antes de tiempo en los primeros años de esta versión.', 'alta', 60000, 150000, 700, 2500, 'moderada', 'published'),
  ('issue-alfa14tb-multiair', 'alfa-1-4-tb', null, 'Averías del sistema de distribución variable MultiAir', 'Ralentí irregular, testigo de motor, pérdida de potencia puntual, en casos graves dificultad de arranque.', 'El sistema MultiAir controla las válvulas de admisión mediante un circuito hidráulico que exige aceite y bujías en buen estado; su electroválvula es un punto de fallo conocido.', 'media', 70000, 160000, 300, 900, 'moderada', 'published'),
  ('issue-outlanderphev-bateria', 'mitsubishi-phev-2-4', null, 'Degradación de la batería de tracción en unidades de muchos km/años', 'Autonomía eléctrica notablemente menor a la original, el motor de gasolina entra con más frecuencia de lo esperado.', 'Envejecimiento normal de la batería de iones de litio; se acelera con cargas rápidas frecuentes o exposición a temperaturas extremas.', 'baja', 120000, null, 0, 4000, 'moderada', 'published'),
  ('issue-meb-software', 'vw-meb-rwd', null, 'Fallos de software e infoentretenimiento en unidades de primeras series', 'Reinicios de la pantalla central, funciones que no cargan (navegación, cámara), actualizaciones OTA fallidas.', 'Software inmaduro en el lanzamiento de la plataforma MEB (ID.3/ID.4/Born/Enyaq de 2020-2021); Volkswagen ha ido publicando actualizaciones.', 'baja', 0, null, 0, 200, 'solida', 'published'),
  ('issue-leaf-bateria-soh', 'nissan-leaf-electric', null, 'Degradación de la batería sin refrigeración líquida', 'Menos barras de capacidad en el salpicadero, autonomía real inferior a la original, más sensibilidad a la carga rápida repetida.', 'La mayoría de versiones del Leaf no llevan refrigeración líquida de la batería, lo que la hace más sensible al calor y a la carga rápida frecuente.', 'media', 100000, null, 0, 6000, 'solida', 'published'),
  ('issue-n47-cadena-2', 'bmw-n47-2-0d', null, 'Desgaste de la cadena de distribución', 'Ruido metálico o ''sonajero'' en el arranque en frío, tintineo bajo carga; en casos avanzados, salto de sincronización del árbol de levas.', 'Tensor y guías de la cadena con desgaste prematuro, especialmente en las unidades fabricadas entre 2007 y 2010.', 'alta', 100000, 200000, 1000, 2200, 'solida', 'published'),
  ('issue-vag20fsi-cadena', 'vag-2-0-fsi', null, 'Consumo de aceite y estiramiento de cadena en la versión turbo (2.0 TFSI)', 'Necesidad de rellenar aceite entre revisiones, ruido de cadena en frío, testigo de motor por desajuste de sincronización.', 'Segmentos de pistón con desgaste prematuro en parte de la producción 2006-2010, y tensor de cadena insuficiente en las primeras versiones turbo.', 'media', 80000, 170000, 400, 2000, 'moderada', 'published'),
  ('issue-psa16thp-cadena', 'psa-1-6-vti', null, 'Estiramiento de la cadena de distribución en la versión turbo (THP)', 'Ruido de cadena en frío, tirón al arrancar, testigo de motor por desajuste de sincronización.', 'El tensor de cadena de las primeras series del 1.6 THP (co-desarrollado con BMW) puede desgastarse antes de tiempo.', 'media', 90000, 180000, 600, 1400, 'moderada', 'published'),
  ('issue-om651-admision', 'mercedes-om651', null, 'Acumulación de carbonilla en el colector de admisión y averías de EGR', 'Pérdida de potencia, testigo de motor, ralentí irregular; en casos avanzados, entrada en modo de emergencia.', 'Acumulación de carbonilla en las aletas del colector de admisión variable y en la válvula EGR, acentuada por uso urbano.', 'media', 100000, 200000, 300, 900, 'moderada', 'published'),
  ('issue-jeep30crd-egr', 'jeep-3-0-crd', null, 'Averías de EGR y sistema de postratamiento', 'Pérdida de potencia, testigo de motor, entrada en modo de emergencia, avisos de sistema anticontaminación.', 'El sistema de postratamiento (EGR, SCR) de este V6 diésel de origen Mercedes/VM Motori es exigente y requiere mantenimiento estricto.', 'media', 100000, 200000, 400, 1500, 'moderada', 'published'),
  ('issue-lrsdv6-admision', 'landrover-3-0-sdv6', null, 'Carbonilla en el colector de admisión y averías de EGR', 'Pérdida de potencia, testigo de motor, ralentí irregular con muchos kilómetros.', 'Acumulación de carbonilla en las aletas del colector de admisión variable, acentuada por uso urbano.', 'media', 100000, 200000, 400, 1200, 'moderada', 'published')
