insert into comparisons (id, slug, left_generation_id, right_generation_id, editorial_summary, takeaways, status, reviewed_at) values
  ('cmp-320d-g20-vs-a4-b9', 'bmw-320d-g20-vs-audi-a4-40-tdi-b9', 'bmw:serie-3:g20', 'audi:a4:b9', 'Dos berlinas diésel de referencia para quien hace kilómetros. El BMW 320d G20 prioriza el tacto de conducción y la tracción trasera; el Audi A4 40 TDI B9 apuesta por el aislamiento, la sensación de solidez y una interfaz algo más sencilla. En consumo real de autovía están muy parejos.', '{"Conducción: el Serie 3 G20 es más ágil y comunicativo; el A4 B9, más neutro y aislado.","Fiabilidad: en ambos hay que vigilar la gestión de gases (EGR/AdBlue). En el BMW, además, la cadena del B47; en el Audi, el sistema SCR de algunas unidades.","Coste de uso: mantenimiento y neumáticos algo más caros en el BMW; retención de valor ligeramente superior en el Serie 3.","Recomendación: 320d si valoras cómo conduce; A4 40 TDI si priorizas confort y previsibilidad."}'::text[], 'published', '2026-09-01'),
  ('cmp-corolla-e210-vs-leon-kl', 'toyota-corolla-125h-vs-seat-leon-1-5-etsi', 'toyota:corolla:e210', 'seat:leon:kl', 'El compacto híbrido ''sin sorpresas'' frente al compacto turbo-gasolina del Grupo VW. El Corolla 125h gana en fiabilidad esperada y consumo urbano; el León 1.5 eTSI ofrece un interior más moderno, mejor maletero en carrocería Sportstourer y una conducción más ágil.', '{"Consumo urbano: claramente a favor del Corolla híbrido (a menudo 4-5 l/100 km).","Fiabilidad esperada: el Corolla parte con ventaja por su mecánica sin turbo ni embrague convencional.","Tecnología e interior: el León se siente más nuevo; multimedia mejor resuelta tras actualizaciones.","Recomendación: Corolla para uso urbano y tranquilidad; León si priorizas conducción, maletero y equipamiento."}'::text[], 'published', '2026-09-01'),
  ('cmp-tucson-nx4-vs-sportage-nq5', 'hyundai-tucson-nx4-vs-kia-sportage-nq5', 'hyundai:tucson:nx4', 'kia:sportage:nq5', 'Mismo coche por debajo: plataforma y motores compartidos (1.6 T-GDi, 1.6 CRDi, híbridos). La decisión se juega en diseño, ajuste de suspensión y, sobre todo, garantía: 5 años en Hyundai frente a 7 años en Kia.', '{"Mecánica: idéntica; los consejos de compra (revisar caja DCT, cuidar el aceite) valen para ambos.","Garantía: 7 años Kia vs 5 años Hyundai, transferible al comprar de segunda mano si está al día.","Confort: el Tucson tiende a un tarado algo más blando; el Sportage, ligeramente más firme.","Recomendación: si dudas, la garantía más larga del Sportage suele inclinar la balanza."}'::text[], 'published', '2026-09-01'),
  ('cmp-clio-etech-vs-208-puretech', 'renault-clio-e-tech-vs-peugeot-208-puretech', 'renault:clio:bja', 'peugeot:208:p21', 'Dos superventas del segmento B con filosofías distintas. El Clio E-Tech híbrido destaca por consumo urbano y maletero; el 208 PureTech seduce por diseño e interior, pero arrastra la duda de la correa de distribución en las series 2019-2021.', '{"Consumo: ventaja para el Clio E-Tech en ciudad; el 208 BlueHDi diésel es la alternativa sobria en carretera.","Punto crítico: en el 208 PureTech hay que verificar sí o sí el estado y el historial de la correa ''húmeda''.","Maletero y habitabilidad: mejores en el Clio.","Recomendación: Clio E-Tech para tranquilidad y ciudad; 208 si te enamora su diseño y compruebas la correa."}'::text[], 'published', '2026-09-01'),
  ('cmp-golf8-vs-a3-8y', 'volkswagen-golf-8-vs-audi-a3-8y', 'volkswagen:golf:mk8', 'audi:a3:8y', 'Plataforma, motores y cajas idénticos. Cambian el precio de ocasión (mejor en el Golf), la percepción de calidad interior (a favor del A3) y algún detalle de equipamiento y ajuste de chasis.', '{"Mecánica: la misma. Verificar software de infoentretenimiento actualizado en ambos y probar la DSG.","Precio de ocasión: el Golf 8 suele salir algo más barato a igualdad de motor y año.","Interior: el A3 transmite algo más de calidad y estatus.","Recomendación: Golf 8 por relación precio/producto; A3 8Y si valoras la imagen premium y el interior."}'::text[], 'published', '2026-09-01'),
  ('cmp-golf7-vs-leon5f', 'volkswagen-golf-7-vs-seat-leon-mk3', 'volkswagen:golf:mk7', 'seat:leon:5f', 'Dos compactos de ocasión sobre la misma plataforma MQB. El Golf VII retiene mejor el valor y transmite algo más de calidad; el León Mk3 sale más barato y tiene un punto más de dinamismo.', '{"Mecánica: idéntica (1.0/1.4/1.5 TSI, 1.6/2.0 TDI). Los consejos de compra valen para ambos.","Precio de ocasión: el León Mk3 suele salir claramente más barato a igualdad de año y motor.","Retención de valor: mejor en el Golf VII.","Recomendación: León Mk3 por relación precio/producto; Golf VII si priorizas reventa y percepción de calidad."}'::text[], 'published', '2026-09-01'),
  ('cmp-qashqai-j11-vs-kadjar', 'nissan-qashqai-j11-vs-renault-kadjar', 'nissan:qashqai:j11', 'renault:kadjar:ha', 'Mismo fondo técnico de la Alianza: comparten plataforma y motores (1.5 dCi, 1.2/1.3 TCe). La decisión se juega en diseño, equipamiento y precio de ocasión.', '{"Mecánica: prácticamente la misma; el 1.5 dCi es la opción más tranquila en ambos.","Puntos a vigilar: consumo de aceite del 1.2 TCe y caja automática (CVT en el Nissan, EDC en el Renault).","El Qashqai suele tener más oferta y mejor reventa; el Kadjar, precio de compra algo menor.","Recomendación: elige por diseño y por la unidad concreta con mejor historial; mecánicamente están empatados."}'::text[], 'published', '2026-09-01'),
  ('cmp-rav4-vs-cx5', 'toyota-rav4-hybrid-vs-mazda-cx-5', 'toyota:rav4:xa50', 'mazda:cx-5:kf', 'El SUV medio híbrido más racional frente al que mejor se conduce. El RAV4 Hybrid gana en consumo urbano y fiabilidad esperada; el CX-5 ofrece mejor tacto de conducción y un interior que fue subiendo de calidad.', '{"Consumo: claramente a favor del RAV4 Hybrid, sobre todo en ciudad.","Conducción e interior: el CX-5 se siente más premium y noble al volante.","Mecánica: el RAV4 híbrido no tiene turbo ni embrague; el CX-5 diésel 2.2 pide recorridos largos.","Recomendación: RAV4 Hybrid para tranquilidad y ahorro; CX-5 si valoras cómo se conduce y el interior."}'::text[], 'published', '2026-09-01'),
  ('cmp-x1-vs-q3', 'bmw-x1-f48-vs-audi-q3-f3', 'bmw:x1:f48', 'audi:q3:f3', 'Dos SUV premium compactos de kilómetros. El X1 F48 prioriza espacio y un diésel B47 sobrio; el Q3 F3 ofrece un interior algo más cuidado y mecánicas del Grupo VW muy conocidas.', '{"Espacio: muy parejo; el X1 aprovecha muy bien el interior para su tamaño.","Puntos a vigilar: cadena y EGR del B47 en el BMW; DSG y Haldex en el Audi.","Interior: ligera ventaja para el Q3 en percepción de calidad.","Recomendación: X1 sDrive18d o Q3 35 TDI según cuál encuentres con mejor historial y precio."}'::text[], 'published', '2026-09-01'),
  ('cmp-giulia-vs-serie3', 'alfa-romeo-giulia-vs-bmw-serie-3-g20', 'alfa-romeo:giulia:952', 'bmw:serie-3:g20', 'Dos berlinas de tracción trasera con vocación deportiva. La Giulia aporta un chasis muy celebrado y una imagen diferente a lo habitual; el Serie 3 G20 ofrece mayor madurez mecánica, más red de talleres y mejor retención de valor.', '{"Chasis: ambas están entre lo mejor del segmento; la Giulia tiene un punto más de ligereza en la dirección.","Fiabilidad percibida: mejor reputación para el BMW; la Alfa Romeo exige revisar bien el historial de mantenimiento.","Red de talleres y recambios: mucho más amplia para el Serie 3.","Recomendación: Serie 3 si priorizas tranquilidad y reventa; Giulia si buscas algo diferente y asumes el riesgo."}'::text[], 'published', '2026-09-01'),
  ('cmp-model3-vs-serie3', 'tesla-model-3-vs-bmw-serie-3-g20', 'tesla:model-3:default', 'bmw:serie-3:g20', 'Eléctrico contra diésel en la berlina media. El Model 3 gana en coste por kilómetro si cargas en casa y en tecnología de a bordo; el 320d ofrece autonomía sin depender de cargadores y una red de talleres mucho más amplia y conocida.', '{"Coste de uso: mejor para el Model 3 si cargas en casa a tarifa valle; el 320d es más previsible si no tienes dónde cargar.","Autonomía y viajes largos: ventaja clara para el diésel fuera de la red de carga rápida.","Mantenimiento: mínimo en el Model 3 (sin distribución ni aceite de motor); el 320d tiene un plan de mantenimiento convencional bien conocido.","Recomendación: Model 3 si tienes dónde cargar a diario y haces trayectos moderados; 320d si haces muchos kilómetros de carretera sin planificar cargas."}'::text[], 'published', '2026-09-01'),
  ('cmp-evoque-vs-q3', 'land-rover-evoque-vs-audi-q3', 'land-rover:evoque:l551', 'audi:q3:f3', 'Dos SUV premium compactos con enfoques distintos. El Evoque prioriza diseño y una capacidad todocamino superior a la media premium; el Q3 ofrece mecánicas del Grupo VW más conocidas y un coste de mantenimiento más contenido.', '{"Diseño: el Evoque tiene una propuesta más arriesgada y reconocible.","Mecánica y mantenimiento: el Q3 usa motores del Grupo VW muy extendidos; el Evoque tiene un coste de reparación superior a la media.","Capacidad todocamino: mejor para el Evoque, aunque pocos compradores la exploten a fondo.","Recomendación: Q3 si priorizas coste de mantenimiento y mecánica conocida; Evoque si el diseño pesa más en tu decisión."}'::text[], 'published', '2026-09-01'),
  ('cmp-xc90-vs-x5', 'volvo-xc90-vs-bmw-x5-g05', 'volvo:xc90:256', 'bmw:x5:g05', 'Dos SUV grandes premium de 7 y 5 plazas respectivamente. El XC90 destaca por seguridad, confort y una tercera fila real; el X5 G05 ofrece un punto más de dinamismo y una gama de motores más amplia.', '{"Plazas: el XC90 ofrece una tercera fila más usable; el X5 se queda en 5 plazas.","Confort y seguridad: el XC90 es de los SUV con mejor reputación en ambos aspectos.","Dinámica de conducción: ligera ventaja para el X5, sobre todo con motores B57/B58.","Recomendación: XC90 si necesitas 7 plazas y priorizas confort; X5 si buscas más dinamismo y no necesitas la tercera fila."}'::text[], 'published', '2026-09-01')
